window.__LEX={"G3000":"<h1>latreuo</h1>\n<p>Strong n° 3000 <i>Prononciation [lat-ryoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>servir pour des gages</li>\n<li>servir, administrer, ou des dieux ou des hommes, et utilisé pour des esclaves ou des hommes libres\n<ol type=\"a\">\n<li>dans le N.T., rendre un culte, faire le service, adorer</li>\n<li>faire les services sacrés, offrir des dons, adorer Dieu dans l'observation des rites institués pour son culte\n<ol>\n<li>sacrificateurs : officier, avoir à charge l'office sacré</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λατρεύω<br>      1</b> être serviteur à gages, SOL. <i>13, 48 ;</i><br><b>      2</b> servir, <i>en gén. (en parl. d’hommes libres ou d’esclaves</i>) : τινί, XÉN. <i>Cyr. 3, 1, 36 ;</i> SOPH. <i>Tr. 35, O.C. 105 ;</i> EUR. <i>Cycl. 24, etc. ;</i> τινά, EUR. <i>El. 131, I.T. 1115,</i> qqn ; θεῷ, NT. <i>Hebr. 9, 14,</i> être ministre de Dieu ; καλὸν πόνον, EUR. <i>Ion 129,</i> s’acquitter, en servant, d’une noble tâche ; <i>fig</i>. τοῖς νόμοις, XÉN. <i>Ages. 7, 2,</i> être esclave des lois ; τῇ ἡδονῇ, LUC. <i>Nigr. 15,</i> du plaisir ; καιρῷ, Ps.-PHOCYL. <i>121,</i> se plier aux circonstances.<br><span><b>Étym</b>. λάτρις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λατρευω - λατρεύω</font>\n<br><br>vient de latris (un domestique loué)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n22 fois dans 21 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (3)</li>\n<li>Actes (5)</li>\n<li>Romains (2)</li>\n<li>Philippiens (2)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (6)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G3001":"<h1>lachanon</h1>\n<p>Strong n° 3001 <i>Prononciation [lakh'-an-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>toute plante comestible, légumes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λάχανον, ου (τὸ)</b> <span>[ᾰᾰ]</span><br><b>      1</b> légume, plante potagère, PLAT. <i>Rsp. 372</i> c ; DÉM. <i>1225, 14 ;</i> TH. <i>H.P. 7, 1, 2, etc. ;</i> λάχανα ἄγρια, AR. <i>Th. 456, etc</i>. plantes potagères non cultivées ;<br><b>      2</b> <i>au pl</i>. τὰ λάχανα, AR. <i>Lys. 557 ;</i> ALEX. (<i>Com. fr. 3, 403) etc</i>. marché aux légumes.<br><span><b>Étym</b>. λαχαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λαχανον - λάχανον</font>\n<br><br>vient de lachaino (bêcher)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G3002":"<h1>Lebbaios</h1>\n<p>Strong n° 3002 <i>Prononciation [leb-bah'-yos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lebbée (Angl. Lebbaeus) = « un homme de cœur »\n<ol>\n<li>un des noms de Jude, qui fut l'un des douze apôtres</li>\n<li>appelé aussi Thaddée, d'après Origène</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λεββαιος - Λεββαῖος</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>","G3003":"<h1>legeon</h1>\n<p>Strong n° 3003 <i>Prononciation [leg-eh-ohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une légion, un corps de soldats dont le nombre a varié selon les époques, et qui, du temps d'Auguste semble avoir été de 6826 hommes, (c.à.d 6100 fantassins et 726 cavaliers)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λεγεών, ῶνος (ἡ)</b> = <i>lat</i>. legio, légion, PLUT. <i>Rom. 13 ;</i> NT. <i>Matth. 26, 53</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεγιων - λεγιών</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3004":"<h1>lego</h1>\n<p>Strong n° 3004 <i>Prononciation [leg'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dire, parler\n<ol type=\"a\">\n<li>affirmer, maintenir, soutenir</li>\n<li>enseigner</li>\n<li>exhorter, conseiller, commander, adresser</li>\n<li>annoncer par la parole, destiner à, moyen de dire</li>\n<li>appeler par le nom, appeler, nommer</li>\n<li>déclarer, mentionner</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>*λέγω</b>, <i>à cause des homonymes avec</i> λέγω² <i>et</i> λέγω³ (ἔλεξα, λέξομαι, <i>etc.) posé par erreur p</i>. λέχω.<br><br>\n➁ <b>λέγω</b> <span>(<i>f</i>. λέξω, <i>ao</i>. ἔλεξα, <i>pf. inus. ; ao. pass</i>. ἐλέχθην)</span><br><b>   I</b> rassembler : λ. ὀστέα, IL. <i>23, 239 ;</i> OD. <i>24, 72,</i> recueillir des ossements ;<br><b>   II</b> choisir, <i>d’où :</i><br><b>      1</b> cueillir : ἀγλαΐην ῥόδου, MOSCH. la fleur brillante d’une rose ;<br><b>      2</b> trier, compter : τινὰ ἐν κήτεσιν, OD. <i>4, 452,</i> compter qqn parmi les monstres de la mer ; τινὰ ἐν ἐχθροῖς, ESCHL. <i>Pr. 973,</i> compter qqn parmi ses ennemis ; <i>au pass</i>. μετὰ τοῖσιν ἐλέχθην, IL. <i>3, 188,</i> je fus compté parmi eux ; λέγεσθαι ἐν τοῖς ἱππικωτάτοις, XÉN. <i>Œc. 11, 20,</i> être compté parmi les plus habiles cavaliers ; <i>fig</i>. regarder comme : τινὰ οὐδαμοῦ, SOPH. <i>Ant. 183,</i> compter qqn pour rien : κέρδος λ. εἰ, SOPH. <i>Ant. 462,</i> compter <i>ou</i> regarder comme un gain si, <i>etc. ;</i><br><b>      3</b> <i>p. suite,</i> énumérer, dire l’un après l’autre : κήδεα, OD. <i>14, 197,</i> énumérer, <i>càd</i>. exposer en détail les soucis de son âme ; τινὶ ὀνείδεα, IL. <i>2, 222,</i> prodiguer les injures à qqn ;<br><b><i>Moy</i>. λέγομαι</b> <span>(<i>f</i>. λέξομαι, <i>ao</i>. ἐλεξάμην)</span><br><b>   I <i>tr</i>.<br>      1</b> rassembler pour soi : ξύλα, IL. <i>8, 507,</i> du bois ; ὀστέα, IL. <i>24, 793,</i> recueillir des ossements ; φάρμακα, A. RH. <i>3, 807,</i> recueillir des poisons ;<br><b>      2</b> choisir : ἄνδρας ἀρίστους, OD. <i>24, 108,</i> les hommes les plus braves ;<br><b>      3</b> énumérer, détailler, <i>d’où</i> redire, <i>acc</i>. IL. <i>13, 275, 292, etc. ;</i> OD. <i>3, 240, etc. ;</i><br><b>   II</b> <i>intr. (au sens réfléchi</i>) se choisir : πέμπτος ἐλέγμην, OD. <i>9, 335,</i> je m’étais choisi moi-même le cinquième.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass</i>. ἐλέχθην, IL. <i>3, 188. Moy. impf. 3 pl. poét</i>. λέγοντο, IL. <i>24, 793 ; fut</i>. λέξομαι <i>au sens pass</i>. EUR. <i>Alc. 322 ; ao.2 sync</i>. ἐλέγμην, OD. <i>9, 335 ; 3 sg</i>. λέκτο, OD. <i>4, 451</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *leǵ-, rassembler ; <i>cf. lat</i>. legō.</span></span><br><br>\n➂ <b>λέγω</b> <span>(<i>impf</i>. ἔλεγον, <i>f</i>. λέξω, <i>ao</i>. ἔλεξα, <i>pf. inus. ; en prose att. on emploie d’ord. pour le fut</i>. ἐρῶ ; <i>pour l’ao., l’ao.2</i> εἶπον, <i>rar. l’ao.1</i> εἶπα ; <i>pour le pf</i>. εἴρηκα ; <i>pass. f</i>. λεχθήσομαι, <i>ao</i>. ἐλέχθην, <i>d’ord</i>. ἐρρήθην ; <i>pf</i>. λέλεγμαι, <i>d’ord</i>. εἴρημαι)</span><br><b>   I</b> dire :<br><b>      1</b> <i>propr</i>. dire, parler, <i>en gén. ; abs</i>. ATT. ; <i>avec un acc. :</i> λ. μῦθον, ESCHL. <i>Pers. 698,</i> prononcer une parole ; λ. ψευδῆ, τἀληθῆ, ESCHL. <i>Ag. 625, etc</i>. dire des mensonges, la vérité ; λ. τί τινι, ATT. dire qqe ch. à qqn ; λόγος λέλεκται πᾶς, SOPH. <i>Ph. 389,</i> j’ai dit tout ce que j’avais à dire ; <i>avec une prop. inf</i>. ATT. <i>ou avec</i> ὡς <i>ou</i> ὅτι, ATT. dire que, <i>etc. ; avec un acc. suivi de</i> ὡς : γυναῖκα λέγουσιν ὡς κάθηται, XÉN. <i>Cyr. 7, 3, 5,</i> on dit que (sa) femme est là assise (à terre) ; <i>avec un part</i>. λέγειν Οἰδίπουν ὀλωλότα, SOPH. <i>O.C. 1580,</i> dire qu’Œdipe est mort, <i>litt</i>. parler d’Œdipe en l’appelant mort ; <i>avec un inf. seul</i> PLAT. <i>Crat. 399</i> d, <i>etc. ; avec une prép</i>. λέγειν ἀμφί τινος, ESCHL. <i>Sept. 1012, etc. ;</i> περί τινος, SOPH. <i>Aj. 150 ;</i> PLAT. <i>Rsp. 410</i> d, <i>etc. ;</i> ὑπέρ τινος, XÉN. <i>Hell. 1, 7, 16 ;</i> SOPH. <i>El. 555,</i> parler sur qqn <i>ou</i> sur qqe ch. ; λ. ἐπί τινι ἀγαθὰς εὐχάς, ESCHL. <i>Suppl. 625,</i> former de bons souhaits pour qqn. ; <i>avec deux acc</i>. ἀγαθὰ λέγειν τινά, AR. <i>Eccl. 435 ;</i> κακὰ λέγειν τινά, HDT. <i>8, 61,</i> dire du bien, du mal de qqn ; <i>avec un adv. et un acc</i>. εὖ λέγειν τινά, dire du bien de qqn (<i>v</i>. εὖ) ; κακῶς λέγειν τινά, dire du mal de qqn (<i>v</i>. κακῶς) ; <i>au pass. avec un suj. de pers. ou de chose :</i> Ἐπύαξα ἐλέγετο Κύρῳ δοῦναι χρήματα πολλά, XÉN. <i>An. 1, 2, 12,</i> on disait qu’Epyaxa avait fait présent à Cyrus de sommes considérables ; <i>cf</i>. XÉN. <i>Cyr. 1, 2, 21, etc. ; ou impers</i>. ἐλέγετο Συέννεσιν εἶναι ἐπὶ τῶν ἄκρων, XÉN. <i>An. 1, 2, 21,</i> on disait que Syennésis était sur les hauteurs ; <i>cf</i>. HDT. <i>8, 119 ;</i> XÉN. <i>Mem. 1, 2, 30, etc. ; pléonast. joint à un autre verbe signifiant</i> « dire », « parler » : ὡς ἔφη λέγων, SOPH. <i>Aj. 757,</i> comme il dit ; <i>cf</i>. HDT. <i>3, 156 ; 5, 36, etc. ;</i> καὶ λέγων εἶπεν, DÉM. <i>108, 13,</i> et il dit ; ὃς ἔφασκε λέγων, AR. <i>Av. 472,</i> qui disait ; ἦ δ' ὃς λέγων, AR. <i>Vesp. 795,</i> et il dit ; <i>abs</i>. ὁ λέγων, ATT. celui qui parle, l’interlocuteur, <i>qqf</i>. l’orateur ; τὸ λεγόμενον, THC. <i>7, 68 ;</i> PLAT. <i>Gorg. 447</i> a, <i>etc.,</i> comme on dit ;<br><b>      2</b> <i>en parl. d’oracles,</i> déclarer, annoncer, HDT. <i>8, 136 ; en parl. d’écrits,</i> dire, annoncer : γράμμασι λέγον τάδε, THC. <i>6, 54</i> (une inscription) dont les caractères disent ceci ; τὰ γράμματα ἔλεγε τάδε, HDT. <i>1, 124,</i> la lettre disait ceci, s’exprimait ainsi ;<br><b>   II</b> dire qqe chose, parler sensément, <i>p. opp. à</i> « parler pour ne rien dire » <i>joint à</i> εὖ, PLAT. <i>Ap. 24</i> e, <i>Prot. 310</i> b, <i>etc. ; à</i> καλῶς <i>ou</i> ὀρθῶς, XÉN. <i>Mem. 3, 3, 4 ; 4, 2, 26 ; avec</i> τι : κινδυνεύεις τι λέγειν, PLAT. <i>Crat. 404</i> e, tu pourrais avoir raison ; ἴσως ἄν τι λέγοις, XÉN. <i>Mem. 2, 1, 12, m. sign. ;</i> οὐδὲν λέγειν, parler pour ne rien dire, AR. <i>Av. 66 ; ou</i> dire un mensonge, PLAT. <i>Ap. 30</i> b ;<br><b>   III</b> désigner, nommer clairement : τὸν ἄνδρα, ἐμὸν λέγω πατέρα, SOPH. <i>Tr. 739,</i> ton mari, je veux dire mon père ; ποταμός, Ἀχελῷον λέγω, SOPH. <i>Tr. 9,</i> un fleuve, je veux dire Akhélôos ; <i>le mot qui sert de rég. à</i> λέγω <i>se construit qqf. en appos. avec le mot à expliquer :</i> Ἀντικλείας τῆς σῆς λέγω τοι μητρός, ESCHL. <i>fr. 172,</i> Antikleia, je veux dire ta mère ; <i>au pass</i>. ὁ λεγόμενος, ἡ λεγομένη, τὸ λεγόμενον, celui, celle, ce qu’on appelle, <i>etc. :</i> ἡ λεγομένη εὐδαιμονία, PLAT. <i>Leg. 695</i> a, ce qu’on appelle le bonheur ; <i>avec un inf</i>. οἱ λεγόμενοι αὐτόνομοι εἶναι, XÉN. <i>Hell. 6, 3, 8,</i> ceux qu’on dit être autonomes ; <i>avec une conj</i>. οἱ λεγόμενοι ὅτι, XÉN. <i>Cyr. 8, 6, 16,</i> ceux dont on dit que, <i>etc. ; p. suite,</i> appeler par son nom : ἃς τρέμομεν λέγειν, SOPH. <i>O.C. 129</i> (les Furies) que nous tremblons d’appeler par leur nom ; <i>ou</i> appeler d’un nom : οὔτοι γυναῖκας ἀλλὰ Γοργόνας λέγω, ESCHL. <i>Eum. 48,</i> ce n’est pas femmes, mais Gorgones que je les appelle ;<br><b>   IV</b> vouloir dire, signifier : τί τοῦτο λέγει ; AR. <i>Eq. 1059,</i> qu’est-ce que cela veut dire ? que signifie cela ? πῶς λέγεις ; PLAT. <i>Ap. 24</i> e, comment dis-tu ? que veux-tu dire ? ποῖόν τί ποτε ἄρα λέγοντές φασι ; PLAT. <i>Theæt. 181</i> c, que peuvent-ils bien vouloir dire en soutenant que, <i>etc. ? ;</i><br><b>   V</b> parler de, vanter : τὴν ἑαυτοῦ ῥώμην, XÉN. <i>Cyr. 1, 3, 10,</i> parler de sa force, la vanter ;<br><b>   VI</b> réciter, chanter : ποιήματα, PLAT. <i>Ion 533</i> e, réciter des poèmes ; Ἀτρείδας, ANACR. <i>23, 1,</i> chanter les Atrides ;<br><b>   VII</b> lire : λαϐὲ τὸ βιϐλίον καὶ λέγε, PLAT. <i>Theæt. 143</i> c, prends le livre et lis (<i>litt</i>. dis) ; λέγε μοι τὸ ψήφισμα, DÉM. <i>516, 30 ; 517, 23, etc</i>. lis-moi le décret ;<br><b>   VIII</b> dire, ordonner, <i>avec l’inf</i>. ESCHL. <i>Ag. 925, Ch. 553 ;</i> τινί <i>avec l’inf</i>. SOPH. <i>O.C. 840 ;</i> XÉN. <i>Cyr. 4, 1, 22,</i> à qqn de faire qqe ch. ; <i>avec</i> μή : ὁ λέγων μὴ μοιχεύειν, NT. <i>Rom. 2, 22,</i> celui qui défend de commettre un adultère ; <i>abs</i>. ὡς ὁ νόμος λέγει, DÉM. <i>599, 14,</i> comme l’ordonne (<i>litt</i>. le dit) la loi ; <i>ou simpl</i>. dire avec insistance, <i>ou</i> avec autorité, SOPH. <i>Ph. 101, etc. ;</i><br><b>   IX</b> parler comme orateur : λέγειν δεινός, SOPH. <i>O.R. 545,</i> habile à parler ; λέγειν δυνάμενος, ISOCR. <i>28</i> b, capable de parler ; λαλεῖν ἄριστος, ἀδυνατώτατος λέγειν, EUP. (PLUT. <i>Alc. 13</i>) très fort pour bavarder, incapable de parler ; λέγειν ἐν ὑμῖν, XÉN. <i>An. 5, 7, 10,</i> parler devant vous ;<br><b>   X</b> faire dire, envoyer dire, XÉN. <i>An. 1, 9, 25 ; 7, 4, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. ind. 3 pl. dor</i>. λέγοντι, PD. <i>O. 9, 49. Fut. 3 pl. dor</i>. λεξοῦντι, PD. <i>fr. 99, 10 Bgk. Pass. pf. en compos</i>. -είλεγμαι, PLAT. <i>Prot. 313</i> b, <i>Ap. 37</i> a. <i>Moy. fut</i>. λέξομαι, <i>au sens pass</i>. SOPH. <i>O.C. 1186 ;</i> EUR. <i>H.f. 582, etc</i>.<span><span><b>Étym</b>. Beekes</span> <i>v</i>. λέγω² ; <i>le sens</i> « dire » <i>développé de</i> « énumérer », <i>cf</i>. λέγω², <i>Moy</i>. I, 3.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεγω - λέγω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1340 fois dans 1238 versets de 25 livres bibliques (NT)\n<ul>\n<li>Matthieu (291)</li>\n<li>Marc (206)</li>\n<li>Luc (227)</li>\n<li>Jean (267)</li>\n<li>Actes (104)</li>\n<li>Romains (35)</li>\n<li>1 Corinthiens (22)</li>\n<li>2 Corinthiens (11)</li>\n<li>Galates (9)</li>\n<li>Ephésiens (7)</li>\n<li>Philippiens (3)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>2 Thessaloniciens (2)</li>\n<li>1 Timothée (4)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Philémon (2)</li>\n<li>Hébreux (33)</li>\n<li>Jacques (8)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (4)</li>\n<li>2 Jean (2)</li>\n<li>Jude (2)</li>\n<li>Apocalypse (93)</li>\n</ul>\n</td></tr>\n</table>","G3005":"<h1>leimma</h1>\n<p>Strong n° 3005 <i>Prononciation [lime'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un reste, le restant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λεῖμμα, ατος (τὸ) :<br>      1</b> reste, résidu, HDT. <i>1, 119 ;</i> PLUT. <i>M. 78</i> a ; <i>particul</i>. la plus petite de deux moitiés, <i>chez les Pythagoriciens,</i> PLUT. <i>M. 1018</i> e ;<br><b>      2</b> <i>t. de mus</i>. demi-ton <i>ou</i> dièse, PLAT. (PLUT. <i>M. 1017</i> f) ; A. QUINT. <i>1, p. 40</i>.<br><span><b>Étym</b>. λείπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λειμμα - λεῖμμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G3006":"<h1>leios</h1>\n<p>Strong n° 3006 <i>Prononciation [li'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lisse, nivelé, uni</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λεῖος, α, ον</b> : lisse, uni :<br><b>   I</b> lisse au toucher, poli, IL. <i>4, 484 ; p. opp. à</i> τραχύς, XÉN. <i>Mem. 3, 10, 1 ;</i><br><b>   II</b> uni, non couvert de broderies, non brodé, THC. <i>2, 97 ;</i> PLAT. <i>Rsp. 310</i> e ;<br><b>   III</b> uni, aplani, <i>en parl. d’emplacements ou de pays</i> (plaine, IL. <i>23, 359 ;</i> HDT. <i>2, 29 ; joint à</i> ὁμαλής, PLAT. <i>Criti. 118</i> a ; route, OD. <i>10, 103 ;</i> HÉS. <i>O. 286 ;</i> HDT. <i>9, 69 ;</i> pays, HDT. <i>7, 9, 2 ;</i> champ labouré, OD. <i>9, 134 ;</i> mer, HDT. <i>2, 117, etc</i>.) ; τὸ λεῖον, ARSTT. <i>H.A. 9, 37,</i> surface unie ; <i>p. opp. à</i> « boisé », <i>joint à</i> ἄξυλος, XÉN. <i>Ath. 2, 12 ; avec un gén</i>. χῶρος λ. πετράων, OD. <i>5, 443 ; 7, 282,</i> terrain sans roches ;<br><b>   IV</b> <i>en parl. de la peau :</i><br><b>      1</b> lisse, sans aspérités, HPC. <i>40, 15 ; en parl. de poissons,</i> sans écailles, <i>p. opp. à</i> λεπιδωτοί, ARSTT. <i>H.A. 2, 13, 10 ;</i><br><b>      2</b> sans poils, <i>p. opp. à</i> δασύς, HPC. <i>1090</i> g ;<br><b>      3</b> sans barbe, LUC. <i>D. mer. 7 ;</i> THCR. <i>Idyl. 5, 90 ; particul</i>. imberbe (à cause de la jeunesse) ANTH. <i>12, 13 ;</i><br><b>   V</b> <i>fig</i>. uni, calme, doux : πνεῦμα, AR. <i>Ran. 1001,</i> vent doux ; <i>en parl. des mouvements du corps,</i> PLUT. <i>M. 1122</i> e ; <i>du son de la voix,</i> PLAT. <i>Rsp. 307</i> a, <i>etc. ;</i> λ. μῦθοι, ESCHL. <i>Pr. 647,</i> douces paroles ; τὸ ἥμερόν τε καὶ λ. (τοῦ ἤθους) PLAT. <i>Crat. 406</i> a, caractère doux et égal ; λ. ἡσυχίη, ANTH. <i>7, 278,</i> calme tranquille ; <i>en parl. du style,</i> uni et coulant, DH. <i>Lys. 24 ;</i> d’une saveur agréable, T. LOCR. <i>100</i> e, <i>joint à</i> γλυκύς.<br><span>•<i> Cp</i>. -ότερος, PLAT. <i>Leg. 833</i> b ; <i>sup</i>. -ότατος, HDT. <i>7, 9, etc. ;</i> ARSTT. <i>H.A. 7, 2, 9</i>.<br><span><b>Étym</b>. <i>p</i>. *λεῖϝος, <i>p.-ê. de la R. indo-europ</i>. *lei-, lisse ; <i>cf. lat</i>. lēvis, <i>v</i>. λίς² <i>et</i> λίς³.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λειος - λεῖος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3007":"<h1>leipo</h1>\n<p>Strong n° 3007 <i>Prononciation [li'-po]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>laisser, quitter, laisser derrière, abandonner, être laissé de côté\n<ol type=\"a\">\n<li>traîner, être inférieur</li>\n<li>être destitué, manquer de</li>\n</ol>\n</li>\n<li>être dans le besoin, faillir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λείπω</b> <span>(<i>f</i>. λείψω, <i>ao.2</i> ἔλιπον, <i>postér. ao.1</i> ἔλειψα, <i>pf</i>. λέλοιπα ; <i>pass. f</i>. λειφθήσομαι, <i>ao</i>. ἐλείφθην, <i>pf</i>. λέλειμμαι, <i>f. antér. au sens du f. simple</i> λελείψομαι)</span><br><b>   I <i>tr</i>.<br>      1</b> laisser, quitter, abandonner, <i>avec un suj. de pers. :</i> τινά, IL. <i>15, 136, etc. ;</i> OD. <i>13, 403 ;</i> ATT. quitter qqn ; βίον, SOPH. <i>El. 1444, etc</i>. quitter la vie ; <i>avec un suj. de ch. :</i> ψυχὴ λέλοιπεν, OD. <i>14, 134,</i> la vie (l’)a abandonné ; τὸν μὲν λίπε θυμός, IL. <i>4, 470,</i> le souffle, <i>càd</i>. la vie l’abandonna ;<br><b>      2</b> laisser derrière soi <i>ou</i> après soi : ἄρρενας, PLAT. <i>Leg. 923</i> e, des enfants mâles ; θυγατέρας, PLAT. <i>Leg. 924</i> e, des filles ; <i>particul</i>. laisser en souvenir, en dépôt : τινί τι, IL. <i>2, 106,</i> qqe ch. à qqn (le sceptre à un successeur) ; <i>fig</i>. εὔκλειαν ἐν δόμοισι, ESCHL. <i>Ch. 349,</i> un renom glorieux dans sa maison ; ἀνίας καὶ γόους τινί, SOPH. <i>Aj. 973,</i> laisser (à d’autres, en mourant) le chagrin et les gémissements (tandis que le mort est délivré des maux) ;<br><b>      3</b> <i>en mauv. part,</i> abandonner par faiblesse <i>ou</i> trahison, délaisser : τινά, SOPH. <i>Ph. 293,</i> abandonner qqn lâchement ; τὴν τάξιν, PLAT. <i>Conv. 179</i> a, <i>etc. ;</i> ESCHN. <i>74, 37,</i> abandonner son poste ; <i>particul. t. de droit att. :</i> τὴν μαρτυρίαν, DÉM. <i>1190, 4,</i> faire défaut comme témoin ; ὅρκον, DÉM. <i>1365, 21,</i> négliger de prêter serment ; φοράν, XÉN. <i>Cyr. 3, 1, 34,</i> négliger de payer un tribut ; <i>avec un suj. de ch. :</i> λίπον ἰοὶ ἄνακτα, OD. <i>22, 119,</i> les traits firent défaut au roi ;<br><b>   II <i>intr</i>.<br>      1</b> s’en aller : λείπουσι καὶ ῥέουσιν αἱ ἐκ τῆς κεφαλῆς τρίχες, ARSTT. <i>H.A. 3, 11, 8,</i> les cheveux s’en vont et tombent de la tête ;<br><b>      2</b> faire défaut, AR. <i>Pl. 859 ;</i> PLAT. <i>Leg. 759</i> e, <i>etc. ; d’où</i> être insuffisant <i>ou</i> incomplet : τί λείπει αὐταῖς ; POL. <i>10, 18, 8,</i> que leur manque-t-il ? <i>avec un adj. de quantité :</i> τριάκοντα ἔτη λείποντα δυοῖν, POL. trente ans moins deux, <i>càd</i>. vingt-huit ; μικρῷ λείπουσιν ἑπτακοσίοις σκάφεσι, POL. avec sept cents barques à peu près ; <i>en gén. avec le gén. de l’objet qui fait défaut :</i> λείποντες κωπῶν, CIA. <i>2, 795 d, 22 (353 av. J.C</i>.) manquant de rames (<i>v. Meisterh. p. 169, 20</i>) ;<br><b>      3</b> <i>p. suite,</i> cesser : οὔποτ' ἔρις λείψει κατ' ἀνθρώπων πόλεις, EUR. <i>Hel. 1157,</i> la discorde ne fera jamais défaut, <i>càd</i>. ne cessera jamais, dans les villes où il y a des hommes ; <i>cf</i>. SOPH. <i>El. 514 ;</i> EUR. <i>H.f. 133</i> ;<br><i>Pass.-moy</i>. <b>λείπομαι</b> <span>(<i>f</i>. λείψομαι, <i>ao.2</i> ἐλιπόμην <i>ou ao. pass</i>. ἐλείφθην, <i>pf</i>. λέλειμμαι)</span> être laissé en arrière, <i>d’où :</i><br><b>      1</b> rester en arrière, EUR. <i>Hipp. 1244, etc. :</i> ἐγὼ λιπόμην ἀκαχήμενος ἦτορ, OD. <i>13, 286,</i> je demeurai là, le cœur triste ; ἐλείποντο τῶν στρατιωτῶν οἱ διεφθαρμένοι ὑπὸ τῆς χιόνος τοὺς ὀφθαλμούς, XÉN. <i>An. 4, 5, 12,</i> ceux des soldats qui avaient les yeux abîmés par la neige demeuraient en arrière ; <i>avec un rég. au gén. :</i> λείπεσθαι βασιλέος, HDT. <i>8, 113,</i> rester en arrière du roi, ne pas le suivre, l’abandonner ; <i>particul</i>. rester en arrière dans une lutte, dans une course : ἀπό τινος, IL. <i>9, 444,</i> rester en arrière de qqn, être distancé, <i>càd</i>. être vaincu par qqn ; <i>p. suite, fig</i>. être vaincu, être inférieur : τινος, ATT. à qqn ; λόγου, SOPH. <i>Aj. 543,</i> rester en arrière d’un discours, d’un propos, <i>càd</i>. n’en pas entendre une parole ; ξύνεσιν οὐδενὸς λ. THC. <i>6, 72,</i> ne le céder en intelligence à personne ; πλήθει τινός, XÉN. <i>Hell. 7, 4, 24,</i> être inférieur en nombre à qqn ; <i>abs</i>. λείπεσθαι μάχῃ, ESCHL. <i>Pers. 344 ;</i> POL. <i>5, 101, 6,</i> être vaincu dans un combat ; ὁ τοῦ λείπεσθαι καιρός, POL. <i>1, 62, 6,</i> le moment de céder ; <i>avec un part</i>. ταῦτα οὐδὲν ἐμοῦ λείπει γιγνώσκων, XÉN. <i>Œc. 18, 5,</i> tu sais cela aussi bien que moi ;<br><b>      2</b> être laissé en arrière, <i>avec idée de temps, càd</i>. survivre, OD. <i>4, 495 ;</i> ESCHL. <i>Pers. 480 ;</i> XÉN. <i>An. 3, 1, 2 ;</i><br><b>      3</b> être dépourvu de, être privé de, <i>gén. :</i> τέκνων, EUR. <i>Ion 680,</i> d’enfants ; κτεάνων καὶ φίλων, PD. <i>I. 2, 11,</i> de biens et d’amis ; <i>fig</i>. γνώμας σοφᾶς, SOPH. <i>El. 474,</i> manquer de jugement, de sagesse, <i>etc. ; abs</i>. être insuffisant, incomplet : ὀλιγέων γάρ σφι ἡμερέων λείπεται σιτία, HDT. <i>9, 45,</i> car il s’en faut de qqes jours qu’ils aient assez de vivres, ils n’ont plus de vivres que pour qqes jours ; <i>d’où impers</i>. λείπεται <i>avec une prop. inf</i>. PLAT. <i>Theæt. 157</i> e, il reste à (faire, dire, <i>etc.) ; abs. avec un suj. de pers</i>. être insuffisant, être incapable de faire qqe ch. SOPH. <i>O.C. 495 ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. λείψομαι, <i>ao</i>. ἐλειψάμην)</span> laisser après soi : μνημόσυνα, HDT. <i>1, 186, etc</i>. des souvenirs ; διαδόχους ἑαυτῷ, PLUT. <i>Æmil. 36,</i> laisser après soi des successeurs.<br><span><b><span class=\"arrow\"></span></b> <i>Ao.2 poét</i>. ἔλλιπον <span>[ῐ]</span> A. RH. <i>2, 1032 ; inf. épq</i>. λιπέειν, HÉS. <i>Sc. 332 ; part. fém. dor</i>. λιποῖσα, SAPPH. <i>83 ;</i> THCR. <i>Idyl. 2, 137. Pl.q.pf. 3 sg. dor</i>. λελοίπη, THCR. <i>Idyl. 1, 139 (var</i>. -πει). — <i>Pass. impf. ou ao. poét. 3 sg. sync</i>. ἔλειπτο, A. RH. <i>1, 45, etc. ; ao. 3 pl. épq</i>. ἔλειφθεν, HH. <i>Merc. 195. — Fut. moy. au sens pass</i>. λείψομαι, HDT. <i>7, 8, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *leik<sup>w</sup>-, laisser derrière soi ; <i>cf. lat</i>. liqu- <i>de</i> reliquus, linquō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λειπω - λείπω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Tite (2)</li>\n<li>Jacques (3)</li>\n</ul>\n</td></tr>\n</table>","G3008":"<h1>leitourgeo</h1>\n<p>Strong n° 3008 <i>Prononciation [li-toorg-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>servir l'état à son propre coût\n<ol type=\"a\">\n<li>assumer une fonction qui doit être administrée par ses propres dépenses</li>\n<li>avoir la charge d'une fonction publique à son propre coût</li>\n<li>rendre un service public à l'état</li>\n</ol>\n</li>\n<li>faire un service, réaliser un travail\n<ol type=\"a\">\n<li>des sacrificateurs et Lévites qui étaient occupés aux rites sacrés au tabernacle ou au temple</li>\n<li>des Chrétiens servant Christ, soit par la prière, soit en instruisant les autres sur les voies du salut, ou d'une autre manière</li>\n<li>de ceux qui aident les autres par leurs ressources, et soulagent leur pauvreté</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λειτουργέω</b>, <i>att</i>. <b>λῃτουργέω-ῶ :<br>      1</b> exercer à ses frais certaines fonctions publiques, AND. <i>17, 19 ;</i> LYS. <i>100, 30 ;</i> DÉM. <i>260 fin, etc. ;</i> λῃτουργίας λῃτουργεῖν, DÉM. <i>1209, 2,</i> exercer certaines fonctions ; λειτουργίαν τῇ πόλει λ. ARSTT. <i>Pol. 4, 4, 16, ou abs</i>. λ. τῇ πόλει, XÉN. <i>Mem. 2, 7, 6,</i> remplir certaines charges pour le bien de l’État ; λ. ὑπέρ τινος, IS. <i>46, 11 ; 62, 39,</i> remplir une charge à la place de qqn ; τὰ λελῃτουργημένα, DÉM. <i>569, 11,</i> les services publics dont on se charge à ses frais ;<br><b>      2</b> servir, <i>en gén. :</i> τινι, ARSTT. <i>Pol. 3, 5, 4 ;</i> ANTH. <i>5, 49,</i> qqn ; τῷ Κυρίῳ λ. NT. <i>Ap. 13, 2,</i> servir le Seigneur ; λ. ἐπὶ τῶν ἱερῶν, DH. <i>2, 22,</i> remplir un ministère sacré ; <i>abs</i>. servir l’État, ARSTT. <i>Pol. 7, 16, 16 ;</i> servir le Seigneur, NT. <i>Hebr. 10, 11 ; ou</i> servir, <i>en gén</i>. CHARÈS (ATH. <i>538</i> e).<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. du 4<sup>e</sup> siècle av. J.C</i>. λῃτουργέω CIA. <i>2, add. 557, 5, 6 (au temps de Démosthène) v. Meisterh. p. 28, 3 ; 30, 4 ; et avec insertion d’un</i> ρ <i>par attraction,</i> ἐλῃρτούργησαν, CIA. <i>2, 172, 4 (340/332 av. J.C</i>.) ; <i>v. Meisterh. p. 62, 1, b ; à partir du 3<sup>e</sup> siècle av. J.C. seul</i>. λειτουργέω, CIA. <i>2, 316, 11 (282/280 av. J.C.), etc. ; v. Meisterh. p. 28, 3</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λειτουργεω - λειτουργέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3009":"<h1>leitourgia</h1>\n<p>Strong n° 3009 <i>Prononciation [li-toorg-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>fonction publique qu'un citoyen entreprend d'administrer avec ses propres fonds</li>\n<li>tout service\n<ol type=\"a\">\n<li>du service militaire</li>\n<li>du service d'un travailleur</li>\n</ol>\n</li>\n<li>usage biblique\n<ol type=\"a\">\n<li>service ou ministère des sacrificateurs relatif aux prières et sacrifices offerts à Dieu</li>\n<li>don ou bienfaisance pour le soulagement des nécessiteux</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λειτουργία</b>, <i>att</i>. <b>λῃτουργία, ας (ἡ) :<br>      1</b> fonction publique, service public, <i>particul. à Athènes, fonction dont le titulaire supportait les dépenses et qui consistait à organiser les chœurs, à équiper les galères, etc</i>. (<i>v</i>. χορηγία, γυμνασιαρχία, ἑστίασις, ἀρχιθεωρία, <i>liturgies ordinaires et annuelles, et</i> τριηραρχία, προεισφορά, <i>liturgies extraordinaires</i>) ISOCR. <i>163</i> b, <i>391</i> d ; PLAT. <i>Leg. 949</i> c, <i>etc. ;</i><br><b>      2</b> service public, <i>en gén. :</i> ὁ ἐπὶ λειτουργιῶν, POL. <i>3, 93, 4,</i> sorte d’intendant préposé à la direction des ouvriers d’administration d’une armée ;<br><b>      3</b> <i>p. ext</i>. service quelconque : ἡ διὰ τοῦ στόματος λειτουργία, ARSTT. <i>P.A. 2, 3, 8, etc</i>. la fonction que remplit la bouche ; φιλικὴ λ. LUC. <i>Salt. 6,</i> service d’ami ;<br><b>      4</b> <i>particul</i>. service du culte : λ. πρὸς τοὺς θεούς, ARSTT. <i>Pol. 7, 10, 11 ;</i> τῶν θεῶν λ. DS. <i>1, 21,</i> service du culte envers les dieux ; <i>d’où abs</i>. service du culte, SPT. <i>Num. 4, 26 ; 8, 22, etc. ;</i> NT. <i>Luc. 1, 23</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans une inscr. att</i>. λῃτουργία, CIA. <i>2, add. 554 b, 14 (386 av. J.C.) v. Meisterh. p. 28, 3</i>.<br><span><b>Étym</b>. λειτουργός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λειτουργια - λειτουργία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philippiens (2)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G3010":"<h1>leitourgikos</h1>\n<p>Strong n° 3010 <i>Prononciation [li-toorg-ik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>relatif à la réalisation d'un service, employé à administrer</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λειτουργικός, ή, όν</b>, propre au service du culte, SPT. <i>Ex. 31, 10 ; Num. 7, 5 ;</i> NT. <i>Hebr. 1, 14</i>.<br><span><b>Étym</b>. λειτουργία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λειτουργικος - λειτουργικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3011":"<h1>leitourgos</h1>\n<p>Strong n° 3011 <i>Prononciation [li-toorg-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un ministère public, le serviteur de l'état</li>\n<li>ministre, serviteur\n<ol type=\"a\">\n<li>fonctionnaires militaires</li>\n<li>du temple\n<ol>\n<li>de celui occupé aux choses saintes</li>\n<li>d'un sacrificateur</li>\n</ol>\n</li>\n<li>des serviteurs du roi</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λειτουργός, ός, όν</b>, qui remplit une fonction publique, <i>d’où subst</i>. ὁ λ. :<br><b>      1</b> <i>à Rome,</i> licteur, PLUT. <i>Rom. 16 ;</i><br><b>      2</b> ouvrier d’administration (charpentier, sapeur, <i>etc.) dans une armée,</i> POL. <i>3, 93, 5 ;</i><br><b>      3</b> ministre du culte : λ. τῶν θεῶν, DH. <i>2, 22 ;</i> λ. θεοῦ, SPT. <i>Ps. 102, 21 ;</i> NT. <i>Rom. 15, 16 ; Hebr. 8, 2 ; en parl. des anges,</i> NT. <i>Hebr. 1, 7 ; abs</i>. PLUT.<br><span><b>Étym</b>. <i>p</i>. *λήϊτα ἔργα, <i>de</i> λαός, ἔργον, <i>cf</i>. λειτουργία, <i>ttef</i>. λειτουργός <i>ne se rencontre pas au sens de</i> « qui remplit une fonction publique à ses frais ; » <i>on disait en ce sens</i> ὁ λειτουργῶν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λειτουργος - λειτουργός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Philippiens (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G3012":"<h1>lention</h1>\n<p>Strong n° 3012 <i>Prononciation [len'-tee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un tissu de lin, serviette\n<ol type=\"a\">\n<li>de la serviette ou tablier que les serviteurs portaient pour accomplir leur travail</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λέντιον, ου (τὸ)</b> = <i>lat</i>. linteum, morceau de toile, linge, M. RUBR. <i>6 ;</i> NT. <i>Joh. 13, 4</i>.<br><span><b>Étym</b>. <i>cf</i>. λίντεον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεντιον - λέντιον</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G3013":"<h1>lepis</h1>\n<p>Strong n° 3013 <i>Prononciation [lep-is']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une écaille, une croûte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λεπίς, ίδος (ἡ)</b> <span>[ῐδ]</span><br><b>   I</b> toute enveloppe qu’on pèle <i>ou</i> qu’on brise (peau, coque, coquille, <i>etc</i>.) HPC. <i>Aph. 1252 ;</i> ANTH. <i>6, 102 ;</i><br><b>   II</b> <i>particul. :</i><br><b>      1</b> coque d’œuf, AR. <i>Pax 198 ;</i><br><b>      2</b> coquille de noix, <i>etc</i>. ANTH. <i>6, 22 ;</i><br><b>      3</b> écaille de poisson, ARSTT. <i>H.A. 1, 1, 9, ou</i> de serpent, NIC. <i>Th. 154 ;</i><br><b>      4</b> lamelle de métal, DS. <i>20, 91 ;</i> PLUT. <i>Phoc. 18 ;</i><br><b>      5</b> éclats de métal qui s’échappent sous le marteau, HPC. <i>614, 15 ;</i> DIOSC. <i>5, 90 ;</i><br><b>      6</b> écaille <i>ou</i> croûte d’une plaie, CELS. <i>2, 12 ;</i><br><b>      7</b> flocon de neige, TH. <i>H.P. 4, 14, 13, au pl. ;</i><br><b>      8</b> sciure, HLD. CHIR. (CHIR. <i>p. 158</i>).<br><span><b>Étym</b>. λέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεπις - λεπίς</font>\n<br><br>vient de lepo (peler)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3014":"<h1>lepra</h1>\n<p>Strong n° 3014 <i>Prononciation [lep'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lèpre</li>\n<li>maladie cutanée très dangereuse, contagieuse, dont le virus peut généralement pénétrer tout le corps, commune en Egypte et en Orient</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λέπρα, ας (ἡ)</b> lèpre, <i>maladie de la peau qui se soulève en écailles,</i> HDT. <i>1, 138 ;</i> HPC. <i>Aph. 1248 ;</i> TH. <i>Sud. 13, etc. ;</i> PLUT. <i>M. 353</i> f, <i>670</i> f ; <i>au pl</i>. HPC. <i>114</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. λέπρη, HDT. <i>l. c. ;</i> HPC. <i>Aph. 1248</i>.<br><span><b>Étym</b>. λέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεπρα - λέπρα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G3015":"<h1>lepros</h1>\n<p>Strong n° 3015 <i>Prononciation [lep-ros']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>couvert d'écailles, rude</li>\n<li>lépreux, affecté de la lèpre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λεπρός, ά, όν :<br>      1</b> écailleux, qui se lève par écailles, <i>d’où</i> lépreux, TH. <i>C.P. 2, 6, 4 ;</i> τὸ λεπρόν, SPT. <i>4Reg. 5, 11,</i> la lèpre ;<br><b>      2</b> raboteux, HPC. <i>Aër. § 79, etc. ;</i> LYC. <i>642 ;</i> ἱμάντες ἐκ λεπρῶν, AR. <i>Ach. 723,</i> courroies de cuir rugueux, <i>càd</i>. de vieux cuir.<br><span><b>Étym</b>. λέπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεπρος - λεπρός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G3016":"<h1>lepton</h1>\n<p>Strong n° 3016 <i>Prononciation [lep-ton']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mince, petit</li>\n<li>petite pièce de cuivre, équivalente au huitième d'un « as », soit quelques centimes</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λεπτόν, οῦ (τὸ) :<br>      1</b> (<i>s.-e</i>. νόμισμα) petite pièce de monnaie, menue monnaie, NT. <i>Luc. 21, 2 ;</i><br><b>      2</b> (<i>s.-e</i>. ἔντερον) l’intestin grêle, HPC. ;<br><b>      3</b> (<i>s.-e</i>. μέρος) minute, soixantième partie d’un degré, SEXT. <i>729, 23 ; 746, 19</i>.<br><span><b>Étym</b>. <i>neutre de</i> λεπτός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεπτον - λεπτόν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G3017":"<h1>Leui</h1>\n<p>Strong n° 3017 <i>Prononciation [lyoo'-ee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lévi (Angl. Levi) = « joindre, attacher »\n<ol>\n<li>le 3ème fils du patriarche Jacob et de son épouse Léa, fondateur de la tribu des Lévites</li>\n<li>le fils de Melchi, un des ancêtres du Christ</li>\n<li>le fils de Siméon, un ancêtre du Christ</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λευι</font> &lt; לוי - <font face=\"Georgia\">Λευί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3018":"<h1>Leuis</h1>\n<p>Strong n° 3018 <i>Prononciation [lyoo-is']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lévi (Angl. Levi) = « joindre, attacher »\n<ol><li>le fils d'Alphée, un collecteur d'impôts (Matthieu l'apôtre)</li></ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λευις - Λευίς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G3019":"<h1>Leuites</h1>\n<p>Strong n° 3019 <i>Prononciation [lyoo-ee'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un membre de la tribu de Lévi</li>\n<li>dans un sens plus étroit, ceux qui étaient appelés Lévites bien que n'étant pas de la race d'Aaron, origine exigée pour le sacerdoce, mais qui servaient comme assistants des sacrificateurs. Leur fonction était de garder les ustensiles sacrés et de veiller à la propreté du temple, d'approvisionner le pain sacré, d'ouvrir et fermer les portes du temple, de chanter les hymnes sacrés dans le temple, et diverses autres choses.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λευΐτης, ου (ὁ)</b> Lévite, NT. <i>Luc. 10, 32 ; Joh. 1, 19 ; Ap. 4, 36 ;</i> PLUT. <i>Qu. conv. 4, 6, 2</i>.<br><span><b>Étym</b>. <i>mot hébr</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λευιτης - Λευίτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3020":"<h1>Leuitikos</h1>\n<p>Strong n° 3020 <i>Prononciation [lyoo-it'-ee-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>Lévitique, appartenant aux Lévites</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λευϊτικός, ή, όν</b>, de Lévite, NT. <i>Hebr. 7, 11 ;</i> τὸ Λευϊτικόν, PHIL. <i>1, 509,</i> le Lévitique, <i>3<sup>e</sup> livre du Pentateuque</i>.<br><span><b>Étym</b>. Λευΐτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λευιτικος - Λευιτικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3021":"<h1>leukaino</h1>\n<p>Strong n° 3021 <i>Prononciation [lyoo-kah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>blanchir, rendre blanc</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λευκαίνω</b> <span>(<i>f</i>. ανῶ, <i>ao</i>. ἐλεύκανα ; <i>pf. pass</i>. λελεύκασμαι)</span><br><b>   I <i>tr</i>.<br>      1</b> rendre blanc, faire blanchir, <i>acc. :</i> λ. ὕδωρ ἐλάτῃσι, OD. <i>12, 172,</i> faire blanchir l’eau avec les rames ; <i>cf</i>. EUR. <i>I.T. 1387, Cycl. 17 ; en parl. du temps,</i> qui fait blanchir les cheveux, la barbe, THCR. <i>Idyl. 14, 70 ; au pass</i>. devenir blanc, blanchir, ARSTT. <i>G.A. 1, 21 ;</i> A. RH. <i>1, 545 ;</i><br><b>      2</b> rendre clair, faire briller : ἠὼς λευκαίνει φῶς, EUR. <i>I.A. 156,</i> l’aurore fait briller sa blanche lumière ;<br><b>   II <i>intr.</i></b> devenir blanc, ARSTT. <i>Probl. 9, 4, 3 ;</i> SPT. <i>Lev. 13, 19 ;</i> ἀφροῖο, NIC. <i>Al. 170,</i> d’écume.<br><span><b>Étym</b>. λευκός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λευκαινω - λευκαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Marc (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3022":"<h1>leukos</h1>\n<p>Strong n° 3022 <i>Prononciation [lyoo-kos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lumière, vif, brillant\n<ol type=\"a\">\n<li>brillant de blancheur, blanc (éblouissant)\n<ol>\n<li>des vêtements des anges, et de ceux élevés à la splendeur de l'état céleste</li>\n<li>vêtements blancs ou brillants portés lors de certaines fêtes</li>\n<li>vêtements blancs symboles de l'innocence et de la pureté de l'âme</li>\n</ol>\n</li>\n<li>blanc de mort\n<ol>\n<li>de la couleur blanche des grains mûrs à la moisson</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>λευκός, ή, όν :<br>   I</b> brillant, <i>d’où :</i><br><b>      1</b> <i>propr</i>. brillant, éclatant : λ. αἴγλη, OD. <i>6, 45,</i> lumière du jour éclatante ; λευκὸν ἠέλιος ὥς, IL. <i>14, 185,</i> brillant comme le soleil (<i>cf</i>. SOPH. <i>Aj. 709 ;</i> EUR. <i>Andr. 1228) ; en parl. d’objets métalliques :</i> λ. λέϐης, IL. <i>23, 268,</i> chaudron brillant ;<br><b>      2</b> clair, pur, limpide, serein : λ. ὕδωρ, IL. <i>23, 282 ;</i> OD. <i>5, 70 ;</i> λ. νᾶμα, EUR. <i>H.f. 573,</i> eau limpide ; λευκότατος ποταμῶν, CALL. <i>Jov. 19,</i> le plus limpide des fleuves ; λ. γαλήνη, OD. <i>10, 94,</i> eaux calmes et brillantes (dans un port) ; <i>p. anal</i>. λευκὴ φωνή, ARSTT. <i>Top. 1, 15, 13,</i> voix claire ; <i>cf</i>. HLD. <i>5, 20 ;</i><br><b>   II</b> <i>p. suite,</i> blanc, <i>p. opp. à</i> μέλας, IL. <i>3, 103 ;</i> HÉS. <i>Sc. 294 ;</i> λευκὸν ἅρμα, EUR. <i>Ph. 172 ;</i> XÉN. <i>Cyr. 8, 3, 12 ;</i> λευκὸν ζεῦγος, DÉM. <i>565, 27,</i> attelage de chevaux blancs ; <i>abs</i>. λευκὸν ἀμπέχεσθαι, AR. <i>Ach. 1024,</i> être vêtu de blanc ; <i>cf</i>. AR. <i>Th. 840 ;</i> λευκὴ γῆ, EUST. <i>ad D. Per. 254,</i> terre blanche, <i>càd</i>. craie ; λευκὴ ῥίζη, HPC. <i>477, 49 ; 571, 50 ; 573, 42,</i> racine blanche, <i>càd</i>. racine de la plante δρακόντιον ; κόμη λευκή, ANACR. (ATH. <i>599</i> c) ; λευκαὶ τρίχες, JUL. <i>366</i> b, <i>ou abs</i>. λευκαί, ESCHL. <i>Ch. 282 ;</i> SOPH. <i>Ant. 1092,</i> cheveux blancs ; <i>d’où</i> λευκὸν γῆρας, SOPH. <i>Aj. 624 ;</i> PLAT. <i>Pol. 270</i> e, vieillesse aux cheveux blancs ; <i>au sens symbolique :</i><br><b>      1</b> <i>comme signe de jeunesse, de beauté :</i> σὰρξ λ. EUR. <i>Med. 1189 ;</i> λ. δέρη, EUR. <i>I.A. 875 ;</i> λ. παρειά, SOPH. <i>Ant. 1239, etc</i>. chair blanche, cou blanc, joue blanche ;<br><b>      2</b> <i>comme signe de nudité, de simplicité :</i> λευκὸς πούς, EUR. <i>Bacch. 665, 863 ; Ion 221,</i> pied nu ;<br><b>      3</b> <i>comme signe de bonheur (p. opp. au</i> noir) : λευκὴ ἡμέρα, MÉN. (ZÉNOB. <i>6, 13) ou</i> λευκὸν ἦμαρ, ESCHL. <i>Pers. 301 ;</i> SOPH. <i>fr. 10,</i> jour de bonheur (<i>cf. lat</i>. candidus dies) ;<br><b>      4</b> <i>comme signe de faiblesse :</i> λευκὰ γήρᾳ σώματα, EUR. <i>H.f. 909,</i> corps blanchis, pâlis par la vieillesse ; λευκαὶ φρένες, PD. <i>P. 4, 109,</i> passions aveugles (incolores) ;<br><b>   III</b> pâle : λ. χρυσός, HDT. <i>1, 50,</i> or pâle (avec alliage d’argent, <i>p. opp. à</i> χρ. ἄπεφθος).<br><span>•<i> Subst</i>. τὸ λευκόν, couleur blanche, AR. <i>Eq. 1279 ;</i> PLAT. <i>Prot. 331</i> d ; <i>ou</i> blanc d’œuf, ARSTT. <i>G.A. 3, 2, 1 ;</i> τὰ λευκά, le blanc des yeux, ALEX. (<i>Com. fr. 3, 486) ; ou</i> leucorrhée, HPC. <i>1128</i> h ; ARSTT. <i>H.A. 7, 1 ;</i> ἡ λευκή (<i>s.-e</i>. ψῆφος) LUC. <i>Harm. 3,</i> caillou blanc, <i>càd</i>. suffrage favorable.<br><span>•<i> Cp</i>. -ότερος, IL. <i>10, 437 ;</i> PD. <i>N. 4, 81 ;</i> XÉN. <i>Œc. 10, 2, etc.</i> <i>• Sup</i>. -ότατος, AR. <i>Eccl. 699 ;</i> CALL. <i>Jov. 19</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *leuk-, blanc ; <i>cf</i>. λεύσσω, λύχνος, <i>lat</i>. lūx, lūmen, <i>etc</i>.</span></span></span><br><br>\n➁ <b>λεῦκος, ου (ὁ)</b> <i>sorte de poisson,</i> THCR. (ATH. <i>284</i> a).<br><span><b>Étym</b>. <i>cf</i>. λευκός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λευκος - λευκός</font>\n<br><br>vient de 'luke' (« lumière »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n25 fois dans 23 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n<li>Apocalypse (16)</li>\n</ul>\n</td></tr>\n</table>","G3023":"<h1>leon</h1>\n<p>Strong n° 3023 <i>Prononciation [leh-ohn']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un lion</li>\n<li>un héros brave et puissant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λέων, οντος (ὁ) :<br>   I</b> lion, IL. <i>5, 782, etc. ;</i> OD. <i>4, 335, etc. ; fig. c. symbole :</i><br><b>      1</b> <i>de cruauté :</i> Ζεύς σε λέοντα γυναιξὶ θῆκε, IL. <i>21, 483,</i> Zeus a fait de toi un lion pour les femmes, <i>en parl. d’Artémis, qui frappe de ses flèches les femmes ;</i><br><b>      2</b> <i>de force ou de courage,</i> ESCHL. <i>Ag. 1259 ;</i> EUR. <i>Or. 1401, etc. ;</i> AR. <i>Th. 514 ;</i> οἴκοι μὲν λέοντες, ἐν μάχῃ δ' ἀλώπεκες, AR. <i>Pax 1189,</i> lions chez eux, dans le combat renards ; ἀντὶ λέοντος πίθηκον γενέσθαι, PLAT. <i>Rsp. 590</i> b, au lieu de lion devenir singe ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> lion, <i>constellation,</i> ARAT. <i>174 ;</i><br><b>      2</b> lion de mer, <i>sorte d’écrevisse,</i> DIPH. SIPHN. (ATH. <i>106</i> c) ;<br><b>      3</b> serpent, NIC. <i>Th. 454 ;</i><br><b>      4</b> sorte de lèpre, ARÉT. <i>Caus. m. diut. 2, p. 69, 14 ;</i><br><b>      5</b> plante, DIOSC. <i>2, 171 ;</i><br><b>      6</b> danse, ATH. <i>629</i> f ;<br><b>   III</b> peau de lion, LUC. <i>H. conscr. 10</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. pl. épq</i>. λείουσι, IL. <i>5, 782 ; 15, 592. Dans ces deux passages, la finale brève antérieure allongée devant</i> λείουσι = *λλείουσι <i>p</i>. *λϝέουσι, <i>de</i> *λέϝουσι, λέων <i>supposant</i> *λέϝων, <i>d’où</i> *λϝέων <i>comme le prouve une inscription attique sur un vase du 7<sup>e</sup>/6<sup>e</sup> siècle av. J.C. où se lit encore un coppa :</i> λϙέων, <i>v. Meisterh. p. 64, 11</i>.<br><span><b>Étym</b>. <i>probabl. emprunt sémitique ; cf</i>. λῖς, <i>fém</i>. λέαινα ; <i>lat</i>. leō <i>est un emprunt</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λεων - λέων</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 4 livres bibliques (NT)\n<ul>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G3024":"<h1>lethe</h1>\n<p>Strong n° 3024 <i>Prononciation [lay'-thay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>oubli, celui qui est oublieux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λήθη, ης (ἡ)</b> oubli, IL. <i>2, 33 ;</i> SOPH. <i>Ph. 878, etc. ;</i> λήθην τινὸς ποιεῖσθαι, HDT. <i>1, 127 ;</i> SOPH. <i>fr. 237, ou</i> ἐμποιεῖν, PLAT. <i>Phil. 63</i> e ; ISOCR. <i>2</i> d, mettre en oubli, oublier ; εἰς λήθην ἐμϐάλλειν τινά, ESCHN. <i>83, 21,</i> mettre qqn en oubli ; λήθη λαμϐάνει τινά, THC. <i>2, 49, ou</i> ἔχει, DÉM. <i>320, 5,</i> l’oubli envahit qqn, qqn oublie ; λήθη τινὸς ἐγγίγνεταί τινι, XÉN. <i>Mem. 1, 2, 21,</i> l’oubli se fait dans l’esprit (des enseignements qu’on a reçus) ; l’Oubli personnifié, HÉS. <i>Th. 227 ;</i> AR. <i>Ran. 186</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. λάθα <span>[ᾱᾱ]</span> PD. <i>O. 2, 20 ; 7, 45 ; N. 8, 24 ; 10, 24 ;</i> SOPH. <i>O.R. 870</i>.<br><span><b>Étym</b>. λανθάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ληθη - λήθη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3025":"<h1>lenos</h1>\n<p>Strong n° 3025 <i>Prononciation [lay-nos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un bac ou réceptacle, cuve, où les grappes sont foulées</li>\n<li>la cuve inférieure dans le sol dans laquelle coule le vin nouveau qui vient du pressoir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ληνός, οῦ (ἡ)</b> objet creux (vase, caisse, <i>etc.) particul. :</i><br><b>      1</b> cuve de pressoir, <i>d’où</i> pressoir, THCR. <i>Idyl. 7, 25 ; 25, 28 ;</i> DS. <i>3, 63 ;</i><br><b>      2</b> auge pour faire boire le bétail, HH. <i>Merc. 104 ;</i> SPT. <i>Gen. 30, 38 ;</i><br><b>      3</b> huche, pétrin, MÉN. (POLL. <i>7, 5 ; 10, 24</i>) ;<br><b>      4</b> cercueil, PHÉRÉCR. <i>et</i> ERAST. (POLL. <i>10, 31</i>) ;<br><b>      5</b> cavité où s’emboîte le mât d’un vaisseau, ATH. <i>474</i> f ;<br><b>      6</b> cavité dans la boîte crânienne, HÉROPHIL. (GAL. <i>4, 188</i>).<br><span><b><span class=\"arrow\"></span></b> ὁ λ. ATH. <i>l. c. Dor</i>. λανός <span>[ᾱ]</span> THCR. <i>Idyl. l. c</i>.</span><br><br>\n➁ <b>λῆνος, εος-ους (τὸ)</b> laine, bandelette de laine, ESCHL. <i>Eum. 44 ;</i> NIC. <i>Al. 452 ; pl</i>. A. RH. <i>4, 173, 177</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ληνος - ληνός</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G3026":"<h1>leros</h1>\n<p>Strong n° 3026 <i>Prononciation [lay'-ros]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>parole futile, absurdité, baliverne, sornette, billevesée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λῆρος, ου (ὁ) :<br>   I</b> radotage, <i>càd. :</i><br><b>      1</b> bavardage, sottise, niaiserie, XÉN. <i>An. 7, 7, 41 ;</i> PLAT. <i>Leg. 698</i> a ; AR. <i>Ran. 809, Lys. 860 ;</i> λῆρος, AR. <i>Pl. 23,</i> pure niaiserie ! λῆρον ληρεῖς, AR. <i>Pl. 517,</i> tu radotes ;<br><b>      2</b> <i>en parl. de pers</i>. radoteur, PLAT. <i>Charm. 176</i> a ; LUC. <i>D. mer. 10, 3, etc. ;</i><br><b>      3</b> délire, divagation, HPC. <i>Epid. 1, 974 ;</i> CIC. <i>Att. 16, 1, 4 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> objet sans valeur, bagatelle, niaiserie, AR. <i>Pl. 589 ;</i> PLAT. <i>Prot. 347</i> d, <i>Hipp. ma. 304</i> b ; DÉM. <i>36, 18 ; 175, 5 ; en parl. des sophistes,</i> AR. <i>Nub. 359 ;</i><br><b>      2</b> objet frivole, mondain, <i>particul</i>. ornement d’or pour les femmes, LUC. <i>Lex. 9 ;</i> ANTH. <i>6, 292</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ληρος - λῆρος</font>\n<br><br>apparemment un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3027":"<h1>lestes</h1>\n<p>Strong n° 3027 <i>Prononciation [lace-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un voleur, pillard, maraudeur, brigand</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λῃστής, οῦ (ὁ) :<br>      1</b> voleur, brigand, SOPH. <i>Ph. 643 ;</i> EUR. <i>Alc. 769, etc. ;</i> XÉN. <i>Hell. 3, 4, 19 ;</i> DÉM. <i>140, 18 ; 162, 11, etc. ; p. opp. à</i> κλέπτης, PLAT. <i>Rsp. 351</i> c ; <i>fig</i>. λ. τυραννίδος, SOPH. <i>O.R. 535,</i> usurpateur de la royauté ;<br><b>      2</b> <i>particul</i>. pirate, HDT. <i>6, 17 (ion</i>. ληϊστής) ; THC. <i>1, 5, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>À côté de</i> λῃστής, <i>dans une inscr. att</i>. λειστής, CIA. <i>2, 804,</i> b, <i>35 (334 av. J.C</i>.).<br><span><b>Étym</b>. <i>contr. p</i>. ληϊστής, <i>de</i> ληΐζομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ληστης - λῃστής</font>\n<br><br>vient de 'leizomai' (piller)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote celui qui vole à la dérobée\n<br><br> – est pour celui qui vole ouvertement</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n15 fois dans 15 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (3)</li>\n<li>Luc (4)</li>\n<li>Jean (3)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3028":"<h1>lepsis</h1>\n<p>Strong n° 3028 <i>Prononciation [lape'-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui reçoit, recette</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λῆμψις, εως (ἡ)</b> <i>c</i>. λῆψις, NT. <i>Phil. 4, 15</i>.<br><br>\n<b>λῆψις, εως (ἡ) :<br>   I</b> action de prendre :<br><b>      1</b> <i>au pr</i>. action de saisir (avec les mains, avec le bec, <i>etc</i>.) ARSTT. <i>P.A. 3, 1, 15 ; 4, 10, 25 ;</i><br><b>      2</b> action de s’emparer de : πόλεως, THC. <i>4, 114,</i> d’une ville ; <i>cf. 5, 110, etc. ;</i><br><b>      3</b> accès, attaque d’un mal, HPC. <i>453, 40 ; 944</i> f, <i>etc. ;</i><br><b>   II</b> action de recevoir : μισθοῦ, PLAT. <i>Rsp. 346</i> d, un salaire ; <i>p. opp. à</i> ἀπόδοσις, PLAT. <i>Rsp. 332</i> a ; <i>à</i> ἀποϐολή, ARSTT. <i>Rhet. 1, 6, 6 ; au pl</i>. recettes <i>ou</i> revenus, PLAT. <i>Rsp. 343</i> d ; ARSTT. <i>Nic. 4, 1, 43 ;</i><br><b>   III</b> <i>t. de rhét. :</i><br><b>      1</b> proposition, thèse à soutenir (<i>cf</i>. λῆμμα) ARSTT. <i>An. pr. 1, 1, 3 ;</i><br><b>      2</b> choix d’un sujet, LGN <i>10</i>.<br><span><b>Étym</b>. λαμϐάνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ληψις - λῆμψις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3029":"<h1>lian</h1>\n<p>Strong n° 3029 <i>Prononciation [lee'-an]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>excessivement, grandement, au delà de la mesure, extrêmement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λίαν</b> <span>[ᾱ]</span> <i>adv</i>., tout à fait extrêmement, très, fort :<br><b>      1</b> <i>avec un verbe,</i> OD. <i>14, 282 ;</i> λίην πιστεύειν, HDT. <i>4, 96,</i> avoir une confiance excessive ; μὴ λίαν στένε, SOPH. <i>El. 1172,</i> ne te lamente pas à l’excès ;<br><b>      2</b> <i>avec un adj. :</i> λίην μέγα, OD. <i>3, 227 ; 16, 243,</i> trop grand ; λίην τόσον, OD. <i>4, 371,</i> à un point si extraordinaire ; <i>qqf. après l’adj. :</i> θαυμάσια λ. LUC. <i>Pisc. 34,</i> tout à fait admirable ;<br><b>      3</b> <i>avec un adv. :</i> λ. ἑκάς, OD. <i>14, 496,</i> trop loin ; οὐδέ τι λ. οὕτω, OD. <i>13, 238,</i> non tout à fait ainsi ; <i>qqf. après l’adv. :</i> πρωῒ λίαν, PLUT. <i>Crass. 17,</i> de très bonne heure ;<br><b>      4</b> <i>avec un sup. :</i> λίαν βέλτιστα, PLAT. <i>Eryx. 393</i> e, tout à fait, très bien, parfaitement ;<br><b>      5</b> <i>avec</i> καί : καὶ λίην, certes, tout à fait, <i>avec sens emphatique, au commencement de la prop. et du vers :</i> καὶ λ. OD. <i>1, 46,</i> oui, certes ;<br><b>      6</b> <i>entre l’art. et un subst</i>. ἡ λίαν φιλότης, ESCHL. <i>Pr. 123,</i> son amour excessif ; ἡ λ. τρυφή, MÉN. <i>4, 251 Meineke</i> mollesse excessive ;<br><b>      7</b> <i>subst</i>. τὸ λίαν, EUR. <i>Andr. 866 ;</i> PLAT. <i>Crat. 415</i> c, l’excès, la violence.<br><span><b><span class=\"arrow\"></span></b> <i>Dans Hom</i>. <span>[ῑ]</span> <i>à l’arsis,</i> <span>[ῐ]</span> <i>à la thésis, excepté dans la locut</i>. καὶ λίην (<i>ion. p</i>. λίαν) <i>où</i> ι <i>est touj. long ; dans les poètes postérieurs</i> <span>[ῑ̆]</span>; <i>dans les poètes classiques</i> <span>[ᾱ]</span>, <i>postér</i>. <span>[ᾰ]</span>. <i>Ion</i>. λίην, HOM. <i>ll. cc</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιαν - λίαν</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (4)</li>\n<li>Luc (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>2 Timothée (1)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3030":"<h1>libanos</h1>\n<p>Strong n° 3030 <i>Prononciation [lib'-an-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>l'arbre à encens</li>\n<li>le parfum, l'encens</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λίϐανος, ου (ὁ, ἡ)</b> <span>[ῐᾰ]</span><br><b>      1</b> ὁ λ. arbre à encens, HDT. <i>4, 75 ;</i> SOPH. <i>fr. 906 ;</i> TH. <i>H.P. 9, 4, 3 ;</i> DIOSC. <i>1, 83 ;</i><br><b>      2</b> encens, résine odorante, ANTH. <i>6, 231, etc. ; en ce sens, qqf. fém</i>. PD. <i>fr. 87, 2 ;</i> EUR. <i>Bacch. 144 ;</i> NIC. <i>Th. 107</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιβανος - λίβανος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3031":"<h1>libanotos</h1>\n<p>Strong n° 3031 <i>Prononciation [lib-an-o-tos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la résine extraite de l'arbre à encens</li>\n<li>un encensoir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιϐανωτός, οῦ (ὁ)</b> <span>[ῐᾰ]</span><br><b>      1</b> encens, gomme de l’arbre λίϐανος, HDT. <i>2, 86, etc. ;</i> AR. <i>Ran. 871 ;</i> PLAT. <i>Leg. 847</i> b ; TH. <i>H.P. 9, 4, 2 ;</i> χόνδρος λιϐανωτοῦ, LUC. <i>Sat. 16,</i> pain d’encens ; μάννα λιϐανωτοῦ, GEOP. <i>6, 6, 1,</i> encens broyé (<i>cf</i>. λιϐανομάννα) ; λ. ἄρρην, ALCIPHR. <i>2, 4, 16,</i> encens mâle (<i>cf. lat</i>. mascula thura) <i>la meilleure sorte d’encens ;</i><br><b>      2</b> lieu où l’on vend de l’encens, EUP. <i>2-1, 550 Meineke ;</i> CHAMÆL. (ATH. <i>374</i> b) ;<br><b>      3</b> encensoir, NT. <i>Apoc. 8, 3</i>.<br><span><b>Étym</b>. λίϐανος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιβανωτος - λιβανωτός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G3032":"<h1>Libertinos</h1>\n<p>Strong n° 3032 <i>Prononciation [lib-er-tee'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui a été libéré de l'esclavage, un homme libre, ou le fils d'un homme libéré</li>\n<li>« Affranchis », « Libertins » : hommes libres. Fraction de la communauté Juive, ils avaient leur propre synagogue à Jérusalem ; ils s'opposèrent à Etienne, le premier martyr (<a class=\"ref\" data-r=\"ACT6.9\">Actes 6.9</a>). Ils étaient probablement des Juifs qui, faits prisonniers par Pompée et d'autres généraux romains, avaient été déportés à Rome, puis libérés.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιϐερτῖνος, ου (ὁ)</b> = <i>lat</i>. lībertīnus, fils d’un affranchi, affranchi, NT. <i>Ap. 6, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λιβερτινος - Λιβερτῖνος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3033":"<h1>Libue</h1>\n<p>Strong n° 3033 <i>Prononciation [lib-oo'-ay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Libye (Angl. Libya) = « affligé ou pleurant »\n<ol><li>grande région d'Afrique du nord, bordant l'Egypte. c'est la partie qui avait Cyrène comme capitale et était donc appelée Cyrénaïque libyenne, actuelle Tripolitaine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λιϐύη, ης (ἡ)</b> <span>[ῐῠ]</span><br><b>   I</b> <i>Libyè, fille d’Épaphos, mère d’Agénor, de Busiris, etc</i>. ESCHL. <i>Suppl. 316 ;</i> ISOCR. <i>11, 10 Baiter-Sauppe, etc. ;</i><br><b>   II</b> la Libye, <i>dans Homère, de l’Égypte à l’Océan ; d’ord., tantôt l’Afrique entière, tantôt la région entre l’Égypte et les Syrtes,</i> HDT. <i>2, 32, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. Λιϐύα, PD. <i>P. 4, 6, etc. ;</i> THCR. <i>Idyl. 16, 77 ; 17, 87 ;</i> ANTH. <i>7, 166</i>.<br><span><b>Étym</b>. Λίϐυς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λιβυη - Λιβύη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3034":"<h1>lithazo</h1>\n<p>Strong n° 3034 <i>Prononciation [lith-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>frapper à coups de pierres\n<ol type=\"a\">\n<li>lapidation, mode de châtiment chez les Juifs</li>\n</ol>\n</li>\n<li>jeter des pierres sur quelqu'un pour le blesser ou le tuer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιθάζω</b> <span>[ῐ]</span><br><b>      1</b> lancer des pierres, ARSTT. <i>Probl. 5, 8 ;</i> STR. <i>705 ;</i><br><b>      2</b> lancer comme une pierre, POL. <i>10, 29, 5 ;</i><br><b>      3</b> lapider, <i>acc</i>. SPT. <i>2Reg. 16, 6 ;</i> NT. <i>Joh. 10, 31</i>.<br><span><b>Étym</b>. λίθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιθαζω - λιθάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Jean (4)</li>\n<li>Actes (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3035":"<h1>lithinos</h1>\n<p>Strong n° 3035 <i>Prononciation [lith-ee'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>de pierre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λίθινος, η, ον</b> <span>[ῐῐ]</span><br><b>      1</b> fait de pierre, PD. <i>I. 1, 25, etc. ;</i> HDT. <i>2, 141 ;</i> THC. <i>5, 47 ;</i> LUC. <i>Tim. 43, etc. ;</i> τὰ λίθινα, XÉN. <i>Lac. 3, 5,</i> statues de marbre ;<br><b>      2</b> λ. θάνατος, PD. <i>P. 10, 75,</i> mort d’une personne changée en pierre.<br><span><b>Étym</b>. λίθος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιθινος - λίθινος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3036":"<h1>lithoboleo</h1>\n<p>Strong n° 3036 <i>Prononciation [lith-ob-ol-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tuer par lapidation, lapider</li>\n<li>frapper quelqu'un à coups de pierres</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιθοϐολέω-ῶ</b> <span>[ῐ]</span> lapider, PLUT. <i>M. 1011</i> e ; SPT. <i>Ex. 18, 13 ; Lev. 20, 2, etc. ;</i> NT. <i>Marc. 12, 4</i>.<br><span><b>Étym</b>. λιθοϐόλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιθοβολεω - λιθοβολέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3037":"<h1>lithos</h1>\n<p>Strong n° 3037 <i>Prononciation [lee'-thos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une pierre\n<ol type=\"a\">\n<li>de petites pierres</li>\n<li>de pierres de construction</li>\n<li>pierres précieuses</li>\n<li>métaph. de Christ</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λίθος, ου</b> (ὁ, ἡ, <i>v. ci-dessous</i>) :<br><b>   I</b> pierre, <i>particul. :</i> ὁ λ. (<i>en ce sens</i> ἡ λ. OD. <i>19, 496</i>) pierre, substance, <i>p. opp. au bois, aux métaux, etc</i>. IL. <i>4, 510, etc. ;</i> ξεστὸς λίθος, PHIL. BYZ. pierre de taille ; ἀκρότομος λ. PHIL. BYZ. pierre de taille à vive arête ; λ. ἔξωθεν τιθέμενος, PHIL. BYZ. pierre employée en parement ; λίθον τινὰ ποιῆσαι <i>ou</i> θεῖναι, IL. <i>24, 611 ;</i> PLAT. <i>Conv. 498</i> c, faire de qqn un bloc de pierre, pétrifier qqn ; <i>comme emblème de dureté, de cruauté :</i> σοὶ δ' αἰεὶ κραδίη στερεωτέρη ἐστὶ λίθοιο, OD. <i>23, 103,</i> toujours ton cœur est plus dur qu’une pierre ;<br><b>   II</b> ὁ λ. (<i>en ce sens</i> ἡ λ. IL. <i>12, 287</i>) pierre à lancer, <i>particul</i>. pierres que se lançaient les combattants, IL. <i>5, 308 ; 8, 327, etc. ; ou</i> disque, palet, OD. <i>8, 190 ; fig</i>. comme emblème de stupidité, AR. <i>Nub. 1202 ;</i> PLAT. <i>Hipp. ma. 292</i> d, <i>Conv. 198</i> b ; ὥσπερ λίθον ζῆν, PLAT. <i>Gorg. 494</i> a, vivre comme une pierre ;<br><b>   III</b> <i>à Athènes,</i> pierres fixes <i>servant à divers usages :</i><br><b>      1</b> pierres <i>sur lesquelles montait l’orateur dans la Pnyx (cf</i>. βῆμα) AR. <i>Ach. 683, Pax 680, etc. ;</i><br><b>      2</b> pierre <i>de l’agora pour les proclamations des hérauts,</i> PLUT. <i>Sol. 8 ;</i><br><b>      3</b> autel <i>sur l’agora, devant lequel les Thesmothètes prêtaient serment,</i> PLUT. <i>Sol. 25 ;</i><br><b>   IV</b> pierre tombale, CALL. <i>Ep. 7, 1 ;</i><br><b>   V</b> pierre précieuse, CALLIX. (ATH. <i>202</i> d) ; JOS. <i>A.J. 12, 2, 4 ;</i> LUC. <i>Im. 11 ;</i><br><b>   VI</b> ἡ Μαγνῆτις λ. EUR. <i>fr. 571 ;</i> Ἡρακλεία, PLAT. <i>Ion 533</i> d ; <i>ou</i> Λυδία, SOPH. <i>fr. 886 ; ou abs</i>. λ. ARSTT. <i>Phys. 8, 10, 9,</i> pierre de Magnésie, d’Hèraklès, de Lydie, <i>càd</i>. aimant ;<br><b>   VII</b> ἡ λ. PLAT. <i>Gorg. 486</i> d, pierre de touche ;<br><b>   VIII</b> ἡ λ. pierre, calcul vésical, ARSTT. <i>H.A. 3, 15, 2 ;</i><br><b>   IX</b> ὁ λ. sorte de pion pour jouer, THCR. <i>Idyl. 6, 18 ; d’où prov</i>. <span>πάντα λίθον κινεῖν</span>, PARŒM. (<i>v</i>. κινέω) remuer tous ses pions, <i>càd</i>. employer tous les moyens ;<br><b>   X</b> <i>au pl</i>. οἱ λίθοι, XÉN. <i>Cyn. 5, 15,</i> région rocailleuse ;<br><b>   XI</b> ὁ, <i>qqf</i>. ἡ λ. marbre ; λ. λευκός, HDT. <i>4, 87 ou abs</i>. λ. HDT. <i>1, 164,</i> marbre blanc ; Πάριος, PD. <i>N. 4, 81 ;</i> HDT. <i>3, 57 ; ou</i> Παρία, THCR. <i>Idyl. 6, 38 ;</i> LUC. <i>Am. 13 ;</i> Ταινάριος, STR. <i>367,</i> marbre de Paros, du Ténare.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att. au sens de</i> « pierre précieuse » λίθος <i>fém</i>. CIA. <i>2, 676, 9 (385/366 av. J.C.) ; 713, 21 (pas av. 330 av. J.C.) ; v. Meisterh. p. 101, 23</i>.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιθος - λίθος</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n60 fois dans 55 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (9)</li>\n<li>Luc (14)</li>\n<li>Jean (7)</li>\n<li>Actes (2)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Pierre (5)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G3038":"<h1>lithostrotos</h1>\n<p>Strong n° 3038 <i>Prononciation [lith-os'-tro-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>étendue (pavée de pierres)</li>\n<li>un pavé en mosaïque\n<ol type=\"a\">\n<li>lieu proche du 'praetorium' ou palais de Jérusalem</li>\n<li>un appartement dont le sol est constitué de mosaïque</li>\n<li>parties des cours extérieures du temple</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιθό·στρωτος, ος, ον</b> <span>[ῐ]</span><br><b>      1</b> bâti en pierres, SOPH. <i>Ant. 1204 ;</i><br><b>      2</b> pavé en mosaïque, SPT. <i>Cant. 3, 10 ;</i> τὸ λιθόστρωτον, ARR. <i>Epict. 4, 7, 37 ;</i> NT. <i>Joh. 19, 13,</i> mosaïque.<br><span><b>Étym</b>. λ. στρώννυμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιθοστρωτος - λιθόστρωτος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3039":"<h1>likmao</h1>\n<p>Strong n° 3039 <i>Prononciation [lik-mah'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>vanner, séparer la menue paille du grain par vannage</li>\n<li>éparpiller</li>\n<li>écraser en morceaux, moudre en poudre, broyer, fracasser</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λικμάω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao</i>. ἐλίκμησα, <i>pf. inus. ; pass. ao</i>. ἐλικμήθην, <i>pf</i>. λελίκμημαι)</span> vanner, IL. <i>5, 500 ;</i> XÉN. <i>Œc. 18, 6 ; au pass</i>. PLUT. <i>M. 701</i> e ; <i>fig</i>. SPT. <i>Job 27, 21 ;</i> NT. <i>Matth. 21, 44, etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *neik-, agiter <i>des céréales</i> pour les vanner ; <i>cf</i>. λίκνον, <i>p. dissimil. pour</i> *νίκνον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λικμαω - λικμάω</font>\n<br><br>vient de likmos, l'équivalent de liknon (un instrument pour vanner, ou panier)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3040":"<h1>limen</h1>\n<p>Strong n° 3040 <i>Prononciation [lee-mane']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un port, un havre, un port de refuge</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιμήν, ένος (ὁ)</b> <span>[ῐ]</span><br><b>   I</b> port, IL. <i>1, 432, etc. ;</i> ATT. <i>etc. ; plur. au sens du sg</i>. OD. <i>4, 846 ; 5, 404 ; 13, 195 ;</i> SOPH. <i>Ph. 936 ;</i> EUR. <i>Andr. 749, Hel. 521, Hec. 1293, etc. ; avec le gén</i>. λιμένες θαλάσσης, OD. <i>5, 418, 440 ;</i> χείματος, EUR. <i>Andr. 891,</i> port pour s’abriter contre la mer, la tempête ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> endroit pour mettre à l’abri, lieu de dépôt : πλούτου, ESCHL. <i>Pers. 250</i> (la terre de Perse) où sont amassés des trésors ; παντὸς οἰωνοῦ, SOPH. <i>Ant. 1000,</i> séjour d’oiseaux de toute sorte ;<br><b>      2</b> retraite, refuge, asile : ἑταιρίας, SOPH. <i>Aj. 683,</i> de l’amitié ; κακῶν, ESCHL. <i>Suppl. 471,</i> contre les maux ; <i>en parl. du sein de Jocaste,</i> SOPH. <i>O.R. 1208 ;</i><br><b>      3</b> <i>chez les Thessaliens, c</i>. ἀγορά, GAL. <i>6, 29</i>.<br><span><b>Étym</b>. λειμών, <i>cf</i>. λίμνη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιμην - λιμήν</font>\n<br><br>apparemment un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G3041":"<h1>limne</h1>\n<p>Strong n° 3041 <i>Prononciation [lim'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un lac</li>\n<li>étang, marais (de feu)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λίμνη, ης (ἡ) :<br>   I</b> eau stagnante restant après le retrait d’un fleuve <i>ou</i> de la mer, IL. <i>21, 317 ; d’où :</i><br><b>      1</b> marais, étang, TH. <i>H.P. 4, 2, 2, etc. ;</i><br><b>      2</b> lac, IL. <i>2, 711, 865 ; 5, 709 ;</i> XÉN. <i>Hell. 3, 2, 18, etc. ; différ. de</i> ἕλος, PLAT. <i>Criti. 114</i> e, <i>Leg. 824</i> b ; <i>particul</i>. lac creusé de main d’homme, HDT. <i>1, 185, 186, 191 ;</i><br><b>   II</b> mer <i>ou</i> bras de mer, IL. <i>24, 79 ;</i> OD. <i>3, 1, etc. ;</i> ESCHL. <i>Suppl. 529 ;</i> EUR. <i>Hipp. 744, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. λίμνα, ESCHL. <i>Suppl. 529 ;</i> EUR. <i>Hipp. 744, etc</i>.<br><span><b>Étym</b>. λειμών, <i>cf</i>. λιμήν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιμνη - λίμνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (5)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G3042":"<h1>limos</h1>\n<p>Strong n° 3042 <i>Prononciation [lee-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>disette de moisson, famine</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιμός, οῦ (ὁ)</b> <span>[ῑ]</span><br><b>      1</b> faim, besoin de manger, <i>joint à</i> δίψα, IL. <i>19, 166 ;</i> XÉN. <i>Cyr. 3, 1, 3 ; d’où</i> famine, inanition, OD. <i>4, 369 ; 10, 177 ; 12, 332, etc. ;</i> HÉS. <i>O. 241 ;</i> HDT. <i>6, 139, etc. ;</i> THC. <i>2, 54 ;</i> XÉN. <i>Hell. 2, 3, 41, etc. ;</i> λιμῷ θανέειν, OD. <i>12, 342,</i> mourir de faim ; <i>en ce sens qqf</i>. ἡ λ. HH. <i>Cer. 313 ;</i> AR. <i>Ach. 743 ;</i> BION <i>6, 4 ;</i> CALL. <i>fr. 490, etc. ;</i><br><b>      2</b> homme affamé, un meurt-de-faim, POSIDIPP. (ATH. <i>377</i> a).\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιμος - λιμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (4)</li>\n<li>Actes (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G3043":"<h1>linon</h1>\n<p>Strong n° 3043 <i>Prononciation [lee'-non]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>tissus, linges faits de lin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λίνον, ου (τὸ)</b> <span>[ῐ]</span><br><b>A</b> lin, <i>plante,</i> HDT. <i>2, 105 ;</i> XÉN. <i>Ath. 2, 11, 12, etc. ; au plur</i>. PLAT. <i>Pol. 280</i> c ; λίνου σπέρμα, THC. <i>4, 26,</i> graine de lin ;<br><b>B</b> objet fabriqué avec du lin :<br><b>   I</b> fil, EUR. <i>Or. 1431, etc. ; prov</i>. <span>λίνον λίνῳ συνάπτειν</span>, PLAT. <i>Euthyd. 298</i> c, joindre le fil au fil, <i>càd</i>. réunir des choses semblables ; fil des Parques, fil de la vie, IL. <i>20, 128 ;</i> OD. <i>7, 198 ; au pl</i>. THCR. <i>Idyl. 1, 139 ;</i> ὑπὲρ τὸ λίνον, LUC. <i>J. conf. 2,</i> en dépit du destin ;<br><b>   II</b> engin de pêche <i>ou</i> de chasse :<br><b>      1</b> ligne à pêcher, IL. <i>16, 408 ;</i> ESCHL. <i>Ch. 506 ;</i><br><b>      2</b> filet de pêcheur, IL. <i>5, 487 ;</i><br><b>      3</b> filet de chasseur, THCR. <i>Idyl. 8, 58 ; 27, 16 ; fig</i>. D. CHR. <i>v. 2, p. 350 ;</i><br><b>   III</b> tissu de lin :<br><b>      1</b> vêtement de lin, IL. <i>9, 661 ;</i> OD. <i>13, 73, 118 ; au pl</i>. ESCHL. <i>Suppl. 121, 132 ;</i><br><b>      2</b> voile de vaisseau, A. RH. <i>1, 565 ;</i> LUC. <i>Am. 6</i>.<br><span><b>Étym</b>. <i>cf. lat</i>. linum.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λινον - λίνον</font>\n<br><br>probablement un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3044":"<h1>Linos</h1>\n<p>Strong n° 3044 <i>Prononciation [lee'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Linus = « un filet »\n<ol><li>Chrétien à Rome, connu de Paul et de Timothée (<a class=\"ref\" data-r=\"2TI4.21\">2 Timothée 4.21</a>), et qui fut le premier évêque de Rome après les apôtres (64 ap. J.C.), selon Irénée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λίνος, ου (ὁ)</b> <span>[ῐ]</span><br><b>   I</b> Linos, <i>ancien aède de Thèbes, fils d’Apollon et de Kalliopè, maître d’Orphée,</i> THCR. <i>Idyl. 24, 103 ;</i> APD. <i>1, 3, 2 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> chant composé par <i>ou</i> sur Linos, IL. <i>18, 570 ;</i><br><b>      2</b> chant funèbre sur la mort de Linos, HDT. <i>2, 79</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λινος - Λίνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3045":"<h1>liparos</h1>\n<p>Strong n° 3045 <i>Prononciation [lip-ar-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>choses qui appartiennent à un somptueux et délicat style de vie</li>\n<li>gras, luisant, brillant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λιπαρός, ά, όν</b> <span>[ῐᾰ]</span><br><b>   I</b> gras :<br><b>      1</b> gras, onctueux, brillant d’huile, de graisse, de parfums, <i>etc. :</i> λιπαρὸν χωρεῖν ἐκ βαλανείου, AR. <i>Pl. 616,</i> sortir du bain luisant de parfums ; <i>en parl. des cheveux (p. opp. à</i> αὐχμηρός) SIM. <i>fr. 148 ;</i> XÉN. <i>Mem. 2, 1, 31 ;</i> λιπαροὶ κεφαλάς, OD. <i>15, 332,</i> avec les cheveux luisants ; τὰ λιπαρά, AR. <i>fr. 421,</i> mets gras ; τὸ λ. ARSTT. <i>P.A. 2, 5, 2, etc</i>. substance grasse ; <i>différ. de</i> πῖον (graisse visqueuse <i>ou</i> gluante) ARSTT. <i>Meteor. 4, 9, 34, etc. ;</i><br><b>      2</b> <i>p. ext</i>. luisant, brillant d’embonpoint, de vigueur, de fraîcheur : πόδες λ. IL. <i>2, 44,</i> pieds robustes ; στῆθος, AR. <i>Nub. 1011,</i> poitrine robuste ; ὀμμάτων σέλας, THCR. <i>Idyl. 23, 8,</i> éclat brillant des yeux, <i>en parl. d’Hèra,</i> IL. <i>14, 186 ; de Thémis,</i> HÉS. <i>Th. 901 ; en parl. d’animaux,</i> XÉN. <i>Cyr. 1, 4, 11 ;</i><br><b>      3</b> <i>fig</i>. opulent, riche, éclatant, splendide, <i>en parl. du sol, de contrées, de villes :</i> λ. νῆσος, HH. <i>Ap. 38,</i> île fertile ; λ. πόλις, THGN. <i>947,</i> ville magnifique ; <i>en parl. de Thèbes,</i> PD. <i>P. 2, 3 ; de Marathon,</i> PD. <i>O. 13, 106 ;</i> λιπαραὶ Ἀθῆναι, la brillante Athènes, <i>probabl. par allusion aux oliviers de l’Attique ;</i> PD. <i>N. 4, 18, etc. ;</i> EUR. <i>I.T. 1130, etc. ; en parl. de choses :</i> λ. γῆρας, OD. <i>11, 136 ; 19, 368,</i> vieillesse abondamment pourvue de ressources ; λ. θέμιστας τελεῖν, IL. <i>9, 156, 298,</i> payer de riches contributions ; λ. κρήδεμνα, OD. <i>1, 334,</i> voiles brillants, riches bandelettes ; <i>cf</i>. IL. <i>22, 406 ;</i> HÉS. <i>Th. 63 ; en parl. d’odeurs :</i> λ. ὀσμή, ARSTT. <i>An. 2, 9, 5,</i> odeur forte et pénétrante ;<br><b>   II</b> collant, gluant, visqueux, <i>subst</i>. αἱ λιπαραί (<i>s.-e</i>. ἐμπλαστοί) GAL. <i>De cris. 9, 677,</i> sortes d’emplâtres visqueux.<br><span>•<i> Cp</i>. -ώτερος, HDT. <i>3, 23 ;</i> <i>• Sup</i>. -ώτατος, HH. <i>Ap. 38 ;</i> PLAT. <i>Tim. 82</i> d.<br><span><b>Étym</b>. λίπα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιπαρος - λιπαρός</font>\n<br><br>vient de lipos (graisse)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3046":"<h1>litra</h1>\n<p>Strong n° 3046 <i>Prononciation [lee'-trah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une livre, un poids de 12 onces (340 grammes)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λίτρα, ας (ἡ)</b> <i>poids et monnaie :</i><br><b>      1</b> livre de douze onces (<i>à Rome,</i> as libralis) POL. <i>22, 26, 19 ;</i> ANTH. <i>6, 214 ;</i><br><b>      2</b> monnaie d’argent sicilienne de 1 ⅓ d’obole attique <i>ou</i> éginète, COM.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιτρα - λίτρα</font>\n<br><br>origine : Latin (libra)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Jean (2)</li>\n</ul>\n</td></tr>\n</table>","G3047":"<h1>lips</h1>\n<p>Strong n° 3047 <i>Prononciation [leeps]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le vent du sud-ouest</li>\n<li>la partie des cieux d'où souffle le vent du sud-ouest</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>λίψ (ὁ)</b> vent du S. O., <i>propr</i>. « le pluvieux », HDT. <i>2, 25 ;</i> ARSTT. <i>Mund. 4 ;</i> STR. <i>29 ;</i> THCR. <i>Idyl. 9, 11 ; au plur</i>. POL. <i>10, 10, 3 ;</i> DS. <i>3, 29, etc</i>.<br><span><b>Étym</b>. λείϐω.</span><br><br>\n➁ *<b>λίψ (ἡ) :<br>   I</b> roche d’où l’eau dégoutte, ANTH. <i>9, 142 ;</i><br><b>   II.1</b> goutte, A. RH. <i>4, 1454</i> (λίϐα) ;<br><b>      2</b> larme, ESCHL. <i>Eum. 54</i> (λίϐα) ;<br><b>      3</b> libation, ESCHL. <i>Ch. 292</i> (λιϐός).<br><span><b>Étym</b>. λείϐω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λιψ - λίψ</font>\n<br><br>vient probablement de 'leibo' (verser une « libation »)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3048":"<h1>logia</h1>\n<p>Strong n° 3048 <i>Prononciation [log-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une collecte\n<ol type=\"a\">\n<li>argent rassemblé pour le secours du pauvre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λογία, ας (ἡ)</b> collecte pour les pauvres, NT. <i>1Cor. 16, 1 et 2</i>.<br><span><b>Étym</b>. λέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογια - λογεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G3049":"<h1>logizomai</h1>\n<p>Strong n° 3049 <i>Prononciation [log-id'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>compter, décompter, supputer, estimer, calculer, dénombrer\n<ol type=\"a\">\n<li>prendre en compte, faire le compte de\n<ol>\n<li>mettre au compte de quelqu'un, imputer</li>\n<li>chose reconnue comme étant quelque chose, c.à.d comme étant l'équivalent de quelque chose, ayant la même valeur, le même poids</li>\n</ol>\n</li>\n<li>dénombrer parmi, compter avec</li>\n<li>compter, décompter</li>\n</ol>\n</li>\n<li>supputer, estimer, peser des raisonnements, délibérer</li>\n<li>prendre en compte toutes les raisons, rassembler ou déduire\n<ol type=\"a\">\n<li>considérer, prendre en compte, peser, méditer sur</li>\n<li>supposer, juger, estimer</li>\n<li>déterminer, décider</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λογίζομαι</b> <span>(<i>f</i>. ίσομαι, <i>att</i>. ιοῦμαι, <i>ao</i>. ἐλογισάμην, <i>pf</i>. λελόγισμαι ; <i>au sens pass. ao</i>. ἐλογίσθην, <i>pf</i>. λελόγισμαι)</span><br><b>A</b> <i>dép. :</i><br><b>   I</b> calculer, <i>d’où :</i><br><b>      1</b> calculer, compter (<i>avec idée de nombre) acc</i>. HDT. <i>2, 16 ;</i> ATT. ; ψήφοισι, HDT. <i>2, 36,</i> compter avec des cailloux ; ἀπὸ χειρός, AR. <i>Vesp. 656,</i> compter avec ses doigts ; τοὺς τόκους, AR. <i>Nub. 20,</i> calculer les intérêts ; <i>avec une prop. inf. :</i> λ. μύρια εἶναι (τὰ ἔτεα) HDT. <i>2, 145,</i> calculer qu’il y a dix mille ans ; τὰς βλάϐας, ἃς ἐλογίζετο αὑτῷ γεγενῆσθαι, DÉM. <i>572, 1,</i> les dommages qu’il estimait lui être survenus ;<br><b>      2</b> faire entrer dans un compte, compter au nombre de : τὸν Πᾶνα τῶν ὀκτὼ θεῶν λ. εἶναι, HDT. <i>2, 46,</i> compter Pan au nombre des huit dieux ;<br><b>      3</b> porter en compte : δώδεκα μνᾶς, AR. <i>Pl. 381,</i> porter douze mines en compte ; τινί τι, LYS. <i>908, 2 ; 909, 5,</i> mettre qqe ch. au compte de qqn, imputer <i>ou</i> attribuer qqe ch. à qqn ;<br><b>   II</b> <i>fig. :</i><br><b>      1</b> (<i>sans idée de nombre</i>) calculer en soi-même, réfléchir : τι, HDT. <i>7, 8 ;</i> THC. <i>1, 76, etc. ;</i> SOPH. <i>O.R. 460, etc. ;</i> περί τινος, HDT. <i>2, 22 ;</i> XÉN. <i>Mem. 4, 3, 11, etc</i>. à qqe ch. ; πρὸς ἑαυτὸν ὅτι AND. <i>8, 4, ou simpl</i>. λ. ὅτι <i>ou</i> ὡς, XÉN. <i>Hell. 2, 4, 28 ; 6, 4, 6,</i> calculer <i>ou</i> réfléchir que ; <i>avec une prop. au part</i>. Σμέρδιν οὐκ ἔτι ἐόντα λ. HDT. <i>3, 65,</i> considérer que Smerdis n’est plus ;<br><b>      2</b> calculer, s’attendre à : δύο ἢ καὶ πλέους ἡμέρας λ. SOPH. <i>Tr. 944,</i> compter sur deux jours <i>ou</i> même plus ; <i>avec un inf</i>. λογιζόμενοι ἥξειν ἅμα ἡλίῳ δύνοντι, XÉN. <i>An. 2, 2, 13,</i> comptant arriver au coucher du soleil (<i>cf</i>. HDT. <i>7, 176 ; 8, 136 ;</i> EUR. <i>Or. 555</i>) ;<br><b>      3</b> conclure par un raisonnement, inférer : ἔκ τινος ὅτι, XÉN. <i>Hell. 6, 1, 5, ou avec une prop. inf</i>. XÉN. <i>Ages. 7, 3 ;</i> PLAT. <i>Gorg. 524</i> b, conjecturer d’après qqe ch. <i>ou</i> conclure de qqe ch. que, <i>etc. ;</i><br><b>B</b> <i>pass. (à l’ao. et au pf., rar. au part. prés</i>. HDT. <i>3, 95</i>) χρήματα εἰς ἀργύριον λογισθέντα, XÉN. <i>Cyr. 3, 1, 33,</i> somme comptée en argent ; ὁπλῖται ἐλογίσθησαν οὐκ ἐλάττους δισμυρίων, XÉN. <i>Hell. 6, 1, 19,</i> on compta que les hoplites n’étaient pas moins de 20 000 (<i>cf</i>. PLAT. <i>Tim. 34</i> a, <i>Phædr. 246</i> c) ; <i>subst</i>. τὸ λελογισμένον, LUC. <i>Nigr. 1,</i> le raisonnement.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. réc</i>. λογίσομαι, NICÉPH. <i>7, 1 W. ; fut. pass. réc</i>. λογισθήσομαι, NICÉPH. <i>7, 22 W. ; pf</i>. λελόγισμαι, <i>act</i>. LYS. <i>32, 24 ;</i> DÉM. <i>28, 12 ;</i> LUC. <i>Abd. 27 ; pass</i>. EUR. <i>I.A. 922 ;</i> PLAT. <i>Phædr. 246</i>.<br><span><b>Étym</b>. λόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογιζομαι - λογίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n41 fois dans 40 versets de 12 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Romains (19)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (8)</li>\n<li>Galates (1)</li>\n<li>Philippiens (2)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3050":"<h1>logikos</h1>\n<p>Strong n° 3050 <i>Prononciation [log-ik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appartenant au discours ou à la parole</li>\n<li>appartenant à la raison ou la logique\n<ol type=\"a\">\n<li>spirituel, appartenant à l'esprit</li>\n<li>agréable à la raison, suivant la raison, raisonnable, logique</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λογικός, ή, όν :<br>   I</b> qui concerne la parole, <i>càd. :</i><br><b>      1</b> qui sert à la parole : λογικὰ μέρη, PLUT. <i>Cor. 38,</i> les organes de la parole ;<br><b>      2</b> habile à parler, disert, éloquent, NAZ. ;<br><b>      3</b> qui concerne la déclamation : λογικοὶ ἀγῶνες, PHILSTR. <i>522,</i> concours de déclamation ;<br><b>      4</b> qui concerne le discours en prose, D. PHAL. <i>42 ;</i> ὁ λογικός, DL. <i>5, 85,</i> prosateur ; ἡ λογική (<i>s.-e</i>. λέξις) DH. <i>Comp. 11,</i> la prose (<i>p. opp. à</i> μουσική) ;<br><b>   II</b> qui concerne le raisonnement, <i>d’où :</i><br><b>      1</b> raisonnable, doué de raison, T. LOCR. <i>99</i> e ; CHRYSIPP. (PLUT. <i>M. 450</i> d) ;<br><b>      2</b> qui convient au raisonnement : λ. διάλογοι, DL. <i>3, 57,</i> dialogues de raisonnement, <i>en parl. de certains dialogues de Platon ;</i> λ. ἀπόδειξις, ARSTT. <i>G.A. 2, 8, 9,</i> démonstration logique ; λ. συλλογισμοί, ARSTT. <i>Rhet. 1, 1, 11,</i> syllogismes logiques, <i>p. opp. aux</i> συλλογισμοὶ ῥητορικοί ; ἡ λογική (<i>s.-e</i>. τέχνη) CIC. <i>Fin. 1, 7,</i> la science du raisonnement, la logique ; ἡ λογικὴ αἵρεσις, GAL. <i>2, 234,</i> l’école dogmatique, <i>en parl. de médecine ;</i> οἱ λογικοὶ ἰατροί, GAL. <i>2, 303,</i> les médecins dogmatiques.<br><span>•<i> Cp</i>. -ώτερος, ARSTT. <i>Metaph. 12, 5, 7 ;</i> CIC. <i>Att. 13, 19, 5</i>.<br><span><b>Étym</b>. λόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογικος - λογικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\t\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3051":"<h1>logion</h1>\n<p>Strong n° 3051 <i>Prononciation [log'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une parole exprimée brièvement, un oracle divin (les oracles étant généralement brefs)\n<ol type=\"a\">\n<li>dans le N.T., les mots, la parole de Dieu, parole révélée, oracle</li>\n<li>le contenu de la loi Mosaïque</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λόγιον, ου (τὸ)</b> réponse d’oracle, prédiction, HDT. <i>1, 64 ; 4, 178 ; 8, 60 ;</i> EUR. <i>Her. 406 ;</i> THC. <i>1, 8, etc. ;</i> AR. <i>Vesp. 799, etc. ; dans l’Écriture, en parl. des enseignements divins,</i> SPT. <i>Ps. 11, 7 ;</i> NT. <i>Ap. 7, 38, etc. ;</i> τὰ δέκα λόγια, PHIL. <i>2, 208,</i> les dix commandements.<br><span><b>Étym</b>. <i>dim. de</i> λόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογιον - λόγιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3052":"<h1>logios</h1>\n<p>Strong n° 3052 <i>Prononciation [log'-ee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>instruit, un homme de lettres, expert en littérature et arts, spécialement versé dans l'histoire et l'antiquité</li>\n<li>habile dans les discours, éloquent</li>\n<li>rationnel, sage</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λόγιος, α, ον :<br>   I</b> (<i>au sens de</i> parole) :<br><b>      1</b> habile à parler, disert, éloquent (<i>p. opp. à</i> ἄφωνος, qui ne sait rien dire) PLUT. <i>Pomp. 51, etc. ;</i> ὁ λ. Ἑρμῆς, LUC. <i>Pseud. 24 ; ou abs</i>. ὁ Λόγιος, LUC. <i>M. cond. 2,</i> le dieu de l’éloquence, <i>càd</i>. Hermès ;<br><b>      2</b> qui s’exprime en prose, prosateur, <i>particul</i>. qui raconte des légendes <i>ou</i> des histoires non en vers, mais en prose, <i>p. opp. à</i> ἀοιδός, PD. <i>P. 1, 94 ;</i><br><b>   II</b> (<i>au sens de</i> raison) habile à raisonner, <i>d’où :</i><br><b>      1</b> sensé, sage, judicieux, EUR. <i>Ion 602 ;</i><br><b>      2</b> capable de raisonner sur, savant, docte : λ. περὶ τὴν ὅλην φύσιν, ARSTT. <i>Pol. 2, 8, 1,</i> capable de raisonner sur la nature entière ; λ. ἰατρός, HLD. <i>4, 7,</i> médecin capable de raisonner ; <i>en parl. des haruspices tyrrhéniens,</i> PLUT. <i>Syll. 7 ; des devins chaldéens,</i> ARR. <i>An. 7, 16 ; particul</i>. qui connaît les légendes <i>ou</i> l’histoire d’un pays, HDT. <i>1, 1 ; 2, 3, etc. ;</i><br><b>      3</b> <i>en parl. du style, c</i>. μεγαλοπρεπής, D. PHAL. <i>38</i>.<br><span>•<i> Sup</i>. -ώτατος, HDT. <i>2, 77 ;</i> STR. <i>919, etc</i>.<br><span><b>Étym</b>. λόγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογιος - λόγιος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3053":"<h1>logismos</h1>\n<p>Strong n° 3053 <i>Prononciation [log-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un calcul, une supposition</li>\n<li>un raisonneur : tel quelqu'un hostile à la foi chrétienne</li>\n<li>un jugement, une décision : suite à une prise de conscience</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λογισμός, οῦ (ὁ) :<br>   I</b> compte, calcul (<i>avec idée de nombre</i>) : λ. τῶν ἡμερῶν, THC. <i>4, 122,</i> compte du nombre de jours ; τυγχάνειν τοῦ ἀληθοῦς λ. THC. <i>3, 20,</i> trouver le compte vrai ; ἐν λ. ἁμαρτάνειν, PLAT. <i>Rsp. 340</i> d ; <i>joint à</i> ἀριθμός, PLAT. <i>Phædr. 274</i> c ; <i>au pl</i>. les nombres, <i>d’où</i> science des nombres, arithmétique : λογισμοὺς μανθάνειν, XÉN. <i>Mem. 4, 7, 8,</i> apprendre le calcul ; λογισμούς τε καὶ γεωμετρίαν διδάσκειν, PLAT. <i>Prot. 318</i> e, enseigner le calcul et la géométrie ;<br><b>   II</b> compte, calcul (<i>sans idée de nombre</i>), raisonnement, réflexion : λογισμῷ ἐλάχιστα χρῆσθαι, THC. <i>2, 11,</i> réfléchir le moins ; λογισμῷ δοῦναί τι, LYS. <i>192, 37,</i> tenir compte de qqe ch. ; λογισμὸν ἔχειν περί τινος, PLAT. <i>Leg. 805</i> a, appliquer sa réflexion à qqe ch. ; ποιεῖν τι τοιῷδε λογισμῷ ὡς εἰ, <i>etc</i>. XÉN. <i>Hell. 3, 4, 27,</i> faire qqe ch. avec cette pensée que si, <i>etc. ;</i> καθιστάναι τινὰ εἰς λογισμόν, THC. <i>6, 34,</i> donner à croire ; <i>p. suite :</i><br><b>      1</b> raison, motif : ὅσον ἦν ἀνθρωπίνῳ λογισμῷ δυνατόν, DÉM. <i>325, 28,</i> autant qu’il était possible selon les calculs de la raison humaine ; οὐ τοῦ ξυμφέροντος μᾶλλον λογισμῷ ἢ τῆς ἐλευθερίας τῷ πιστῷ, THC. <i>2, 40,</i> non par le compte que l’on tient de l’intérêt plutôt que par la confiance propre à l’indépendance ;<br><b>      2</b> faculté de raisonner, raison, XÉN. <i>Mem. 4, 3, 11 ;</i> ARSTT. <i>Metaph. 1, 1, 3, etc</i>.<br><span><b>Étym</b>. λογίζομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογισμος - λογισμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3054":"<h1>logomacheo</h1>\n<p>Strong n° 3054 <i>Prononciation [log-om-akh-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lutter à propos de mots</li>\n<li>se quereller au sujet de choses vides et insignifiantes</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λογο·μαχέω-ῶ</b> <span>[ᾰ]</span> se battre en paroles, disputer, se quereller, NT. <i>2Tim. 2, 14</i>.<br><span><b>Étym</b>. λόγος, μάχομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογομαχεω - λογομαχέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3055":"<h1>logomachia</h1>\n<p>Strong n° 3055 <i>Prononciation [log-om-akh-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>lutter à propos de mots</li>\n<li>se quereller au sujet de choses vides et insignifiantes</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λογομαχία, ας (ἡ)</b> <span>[μᾰ]</span> combat en paroles, dispute, querelle, NT. <i>1Tim. 6, 4</i>.<br><span><b>Étym</b>. <i>cf</i>. λογομαχέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογομαχια - λογομαχία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3056":"<h1>logos</h1>\n<p>Strong n° 3056 <i>Prononciation [log'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>parole\n<ol type=\"a\">\n<li>parole, émise de vive voix, implique conception ou idée</li>\n<li>ce que quelqu'un a dit\n<ol>\n<li>une parole</li>\n<li>les dires de Dieu</li>\n<li>décret, mandat ou ordre</li>\n<li>préceptes moraux donnés par Dieu</li>\n<li>prophéties de l'Ancien Testament données par les prophètes</li>\n<li>ce qui est déclaré, une pensée, déclaration, un aphorisme, un dicton, une maxime</li>\n</ol>\n</li>\n<li>discours\n<ol>\n<li>l'action de parler, discourir</li>\n<li>faculté de parole, adresse et pratique dans la parole</li>\n<li>une sorte ou un style de discours</li>\n<li>une parole continue et suivie - instruction</li>\n</ol>\n</li>\n<li>doctrine, enseignement</li>\n<li>toute chose rapportée en parole, narration, récit</li>\n<li>matière à discussion, chose dite, affaire, cause de dispute, motif à plaider</li>\n<li>la chose dite ou dont il est question, événement, action</li>\n</ol>\n</li>\n<li>son usage en considération de l'ESPRIT seul\n<ol type=\"a\">\n<li>raison, la faculté mentale de penser, méditer, raisonner, calculer</li>\n<li>prendre en compte, c.à.d avoir égard, considérer</li>\n<li>décompter, faire le point</li>\n<li>réponse ou explication en référence à un jugement</li>\n<li>raison, cause, fond</li>\n</ol>\n</li>\n<li>Dans Jean, le mot dénote la Parole essentielle de Dieu, Jésus-Christ, la sagesse et le pouvoir en union avec Dieu, son ministre dans la création et le gouvernement de l'univers, la cause de toute vie sur terre, physique et morale ; Jésus qui est venu dans une nature humaine pour procurer le salut à l'humanité, le Messie, la seconde personne de la Divinité, qui brille éminemment par ses paroles et ses actions.</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λόγος, ου (ὁ) :<br>A</b> parole :<br><b>   I</b> la parole, <i>en gén. :</i> ἔργα λόγου μέζω, HDT. <i>2, 35,</i> actions au-dessus de ce qu’on en pourrait dire ; λόγου κρεῖσσον, THC. <i>2, 50,</i> au-dessus de toute expression ; <i>p. opp. à</i> ἔργον (l’action) λόγῳ μὲν…, ἔργῳ δέ, HDT. <i>4, 8 ;</i> THC. <i>1, 22, etc</i>. en parole, mais en fait, <i>etc. ;</i> ἔργῳ κοὐ λόγῳ, ESCHL. <i>Pr. 336,</i> en réalité et non en parole ; <i>de même p. opp. à</i> νόῳ (intelligence, esprit, pensée) HDT. <i>2, 100 ; à</i> ἀλήθεια (réalité), LYCURG. <i>150, 44 ;</i><br><b>   II</b> <i>particul</i>. une parole, un mot : ὡς εἰπεῖν λόγῳ, HDT. <i>2, 37 ;</i> λέγειν ἑνὶ λόγῳ, PLAT. <i>Phædr. 241</i> e, <i>etc. ;</i> ὡς ἁπλῷ λόγῳ, ATT. <i>ou</i> ἁπλῷ λόγῳ, ESCHL. <i>Pr. 975,</i> pour le dire en un mot, en un seul mot, d’un simple mot ; <i>au plur</i>. mots, paroles, <i>d’où</i> langage, <i>us. seul. en ce sens dans Hom. et Hés</i>. IL. <i>15, 393 ;</i> αἱμύλιοι λόγοι, OD. <i>1, 56,</i> paroles de flatterie, flatteries ; <i>cf</i>. HH. <i>Merc. 317 ;</i> ψευδεῖς λόγοι, HÉS. <i>Th. 229,</i> mensonges (<i>ttef</i>. λόγος <i>ne signifie jamais</i> « mot » <i>au sens grammatical comme</i> ὄνομα <i>ou</i> ῥῆμα ; <i>il suppose toujours l’usage réel de la parole</i>) ;<br><b>   III</b> <i>p. suite,</i> une parole, <i>pour marquer diverses applications particulières :</i><br><b>      1</b> <i>t. de log</i>. proposition, PLAT. <i>Theæt. 201</i> e, <i>etc. ;</i> λ. ὁριστικός, ARSTT. <i>Metaph. 7, 3, 8,</i> proposition servant à définir, définition ;<br><b>      2</b> ce qu’on dit, un dire, THC. <i>1, 2 ;</i><br><b>      3</b> révélation divine, PLAT. <i>Phæd. 78</i> d ; <i>d’où</i> réponse d’oracle, PD. <i>P. 4, 105 ;</i><br><b>      4</b> sentence, maxime, proverbe, PD. <i>N. 9, 6 ;</i> ESCHL. <i>Sept. 218, etc. ;</i><br><b>      5</b> exemple : λόγου ἕνεκα, PLAT. <i>Crit. 46</i> d ; λόγου χάριν, ARSTT. <i>Nic. 6, 13,</i> par exemple, <i>càd</i>. pour la forme, en apparence ;<br><b>      6</b> décision, résolution, HDT. <i>1, 141, 166, etc. ;</i><br><b>      7</b> condition, HDT. <i>1, 60 ;</i> ἐπὶ λόγῳ, HDT. <i>7, 158,</i> à une condition ;<br><b>      8</b> promesse, SOPH. <i>O.C. 651 ;</i><br><b>      9</b> prétexte, XÉN. <i>An. 6, 2, 6 ;</i> ἐκ σμικροῦ λόγου, SOPH. <i>O.C. 620,</i> sous un prétexte frivole :<br><b>      10</b> argument, XÉN. <i>Cyr. 1, 5, 3, etc. ; An. 2, 6, 3, etc. :</i><br><b>      11</b> ordre, ESCHL. <i>Pr. 17, 40 ; Pers. 363 ;</i><br><b>   IV</b> mention : λόγου ἄξιον, HDT. <i>4, 28</i> (pour que cela) vaille la peine qu’on en parle ; <i>particul. en b. part,</i> renommée, renom : λόγος ἔχει σε, HDT. <i>7, 5, etc</i>. on parle de toi ; περὶ σέο λόγος ἀπῖκται πολλός, HDT. <i>1, 30,</i> ta renommée est venue jusqu’à moi ; λόγον ἀκούειν, ATT. entendre parler de soi (<i>v</i>. ἀκούω) ; <i>en mauv. part :</i> mauvais bruit, mauvaise réputation, SOPH. <i>Aj. 138 ;</i> EUR. <i>Her. 165, etc. ;</i><br><b>   V</b> bruit qui court, bruit répandu : λόγος ἐστί, λόγος ἔχει, λόγος φέρεται, <i>avec une prop. inf</i>. ATT. c’est un bruit répandu que, <i>etc. ;</i> le bruit se répand que, <i>etc. ; rar. avec un n. de pers. pour sujet :</i> Κλεισθένης λόγον ἔχει τὴν Πυθίαν ἀναπεῖσαι, HDT. <i>5, 66,</i> Kleisthénès passe pour avoir inspiré la Pythie ; <i>particul</i>. nouvelle, SOPH. <i>O.C. 1150 ;</i><br><b>   VI</b> entretien, <i>d’où :</i><br><b>      1</b> <i>propr</i>. entretien, conversation : εἰς λόγους ἐλθεῖν, συνελθεῖν, ἰέναι, ἀφικέσθαι τινί, HDT. <i>1, 82 ; 2, 32, etc. ;</i> ATT. ; διὰ λόγων ἰέναι, EUR. <i>Tr. 916 ;</i> διὰ λόγων γίγνεσθαί τινι, POL. <i>22, 21, 12,</i> s’entretenir <i>ou</i> conférer avec qqn ; λόγον περί τινος λέγειν, ANT. <i>135, 22, ou</i> λόγους ποιεῖσθαι πρός τινα, PLAT. <i>Prot. 348</i> a, <i>etc</i>. s’entretenir de qqn <i>ou</i> de qqe ch. ;<br><b>      2</b> discussion, <i>particul</i>. discussion philosophique, PLAT. <i>Gorg. 506</i> a, <i>Prot. 329</i> c, <i>etc. ;</i> οἱ ἐν τοῖς λόγοις, ARSTT. <i>Metaph. 8, 8, 20,</i> les dialecticiens, <i>càd</i>. Platon et son école ;<br><b>   VII</b> récit, <i>d’où :</i><br><b>      1</b> fable, HDT. <i>1, 141 ;</i> XÉN. <i>Mem. 2, 7, 13 ;</i> PLAT. <i>Phæd. 61</i> b, <i>etc. ;</i> ARSTT. <i>Rhet. 2, 20 ;</i> οἱ τοῦ Αἰσώπου λόγοι, PLAT. <i>Phæd. 60</i> d, les fables d’Ésope ;<br><b>      2</b> récit d’histoire, <i>p. opp. à la légende</i> (μῦθος), PLAT. <i>Prot. 320</i> c, <i>Gorg. 523</i> a, <i>etc. ; à l’histoire proprement dite</i> (ἱστορία), HDT. <i>2, 99, etc. ; d’où au plur</i>. traditions historiques, HDT. <i>1, 184, etc. ; à la poésie épique</i> (ἔπος) (<i>sens conservé dans les composés</i> λογογράφος, λογοποιός, <i>etc</i>.) ;<br><b>   VIII</b> <i>par ext</i>. composition en prose (<i>les ouvrages d’histoire ayant été les premiers écrits grecs en prose) p. opp. à</i> ποίησις, PLAT. <i>Rsp. 390</i> a ; <i>à</i> ποίημα, ARSTT. <i>Poet. 2, 5, 6, etc. ; à</i> ᾠδαί, XÉN. <i>Cyr. 1, 4, 25 ;</i> PLAT. <i>Leg. 835</i> a, <i>etc. ; particul. :</i><br><b>      1</b> discours oratoire, discours, ORAT. ; ARSTT. <i>Rhet. 1, 3, etc. (cf</i>. λογογράφος, λογοποιός, <i>etc</i>.) ;<br><b>      2</b> traité de philosophie, de morale, de médecine, <i>etc</i>. HPC. PLUT. ;<br><b>      3</b> ouvrage, <i>en gén. ou</i> partie d’un ouvrage, XÉN. <i>Cyr. 4, 5, 12, etc. ;</i> ἐν τῷ ἔμπροσθεν λόγῳ, XÉN. <i>An. 2, 1, 1 ;</i> ἐν τῷ πρόσθεν λόγῳ, XÉN. <i>An. 3, 1, 1,</i> dans le livre précédent ;<br><b>   IX</b> <i>p. suite, au pl</i>. belles-lettres, sciences, études, <i>en gén. :</i> οἱ ἐπὶ λόγοις εὐδόκιμοι, HDN <i>6, 1,</i> les gens de lettres célèbres ; οἱ λόγοι, ANTH. <i>9, 171,</i> lettres, littérature, compositions littéraires ; οἱ ἔξωθεν λόγοι, ECCL. les études du dehors, <i>càd</i>. profanes ;<br><b>   X</b> <i>p. ext</i>. sujet d’entretien, d’étude <i>ou</i> de discussion (<i>cf. la même relat. de sens pour le mot</i> ῥῆμα) HDT. <i>1, 21, etc. ;</i> ATT. ; περὶ λόγου τινὸς διαλέγεσθαι, PLAT. <i>Ap. 34</i> e, s’entretenir d’un sujet d’étude ; ἐς λόγον τινός, HDT. <i>3, 99 ;</i> πρὸς λόγον τινός, ESCHL. <i>Sept. 519,</i> ce dont il s’agit, l’objet en cause, en discussion, <i>etc. ;</i> ἐὰν πρὸς λόγον ᾖ, PLAT. <i>Phil. 33</i> c, si cela rentre dans le sujet ; μετέχειν τοῦ λόγου, HDT. <i>1, 127,</i> participer à l’objet (de l’entretien) <i>càd</i>. être dans le secret ; <i>p. suite :</i><br><b>      1</b> point de départ d’une discussion, proposition, principe, PLAT. <i>Gorg. 508</i> b ;<br><b>      2</b> définition, PLAT. <i>Phædr. 245</i> e, <i>Rsp. 343</i> a, <i>etc. ;</i> ARSTT. <i>Metaph. 3, 4, 3, etc. ;</i> DL. <i>7, 60 ;</i><br><b>B</b> raison, <i>d’où :</i><br><b>   I</b> faculté de raisonner, raison, intelligence, PLAT. <i>Phædr. 270</i> c, <i>Tim. 52</i> c, <i>etc. ;</i> ἃ μάλιστά τις ἂν λόγῳ λάϐοι, PLAT. <i>Parm. 135</i> e, ce qu’on peut surtout saisir par la raison ; τὰ λόγῳ καὶ διανοίᾳ ληπτά, PLAT. <i>Rsp. 529</i> d, ce que la raison et l’intelligence peuvent saisir ; τῷ λόγῳ ἕπεσθαι, PLAT. <i>Rsp. 582</i> e, <i>586</i> d, prendre la raison pour guide ;<br><b>   II</b> raison, bon sens : ὀρθὸς λόγος, PLAT. <i>Phæd. 73</i> a ; ARSTT. <i>Nic. 6, 1, etc</i>. droite raison ; ὁ ἐοικὼς λόγος, PLAT. <i>Leg. 647</i> d, la juste raison ; μετὰ λόγου, PLAT. <i>Tim. 28</i> a, <i>Theæt. 206</i> e, <i>etc</i>. avec raison ; κατὰ λόγον, PLAT. <i>Rsp. 500</i> c, <i>etc</i>. selon la raison ; ἔχειν λόγον, PLAT. <i>Phæd. 62</i> d, <i>etc</i>. être conforme à la raison, être juste <i>ou</i> raisonnable ; ὡς ἔχει λόγον, DÉM. <i>1090, 12,</i> comme cela est naturel ; οὐκ ἔχει λόγον, SOPH. <i>El. 466, etc</i>. cela n’a pas de raison ; τὸ παρὰ λόγον (<i>c</i>. παράλογος), ATT. ce qui est contraire à la raison ; λόγος αἰτεῖ, <i>avec une prop. inf</i>. ATT. la raison exige que, <i>etc. ;</i><br><b>   III</b> raison intime d’une chose, fondement, motif : κατὰ τίνα λόγον ; PLAT. <i>Rsp. 366</i> b, sur quel fondement ? ἐξ οὐδενὸς λόγου, SOPH. <i>Ph. 730,</i> sans aucune raison ; ὁ λόγος αἱρέει με, HDT. <i>1, 132, etc</i>. la raison de la chose me convainc ; ὁ λόγος οὕτως αἱρέει, <i>avec une prop. inf</i>. HDT. <i>3, 45,</i> la raison des choses veut ainsi que, <i>etc. ;</i><br><b>   IV</b> exercice de la raison, jugement, <i>d’où :</i><br><b>      1</b> opinion : ἅπαντα νικᾶν λόγον, SOPH. <i>O.C. 1225,</i> surpasser tout ce qu’on peut dire <i>ou</i> penser : κατὰ τὸν ἐμόν γε λόγον, NAZ. d’après mon sentiment ;<br><b>      2</b> <i>en b. part :</i> bonne opinion, estime : λόγῳ ἐν σμικρῷ εἶναι, PLAT. <i>Rsp. 550</i> a, être en médiocre estime ; πλείστου λόγου εἶναι, HDT. <i>1, 143 ;</i> ἐλαχίστου λόγου εἶναι, HDT. <i>3, 146,</i> être en très grande, en très petite estime ; λόγου εἶναι πρός τινος, HDT. <i>4, 138,</i> être estimé par qqn ; λόγου οὐδενὸς γενέσθαι πρός τινος, HDT. <i>1, 120,</i> ne jouir d’aucune considération de la part de qqn ; λόγον ἔχειν τινός, HDT. <i>1, 62, 115, etc. ;</i> λόγον ἴσχειν περί τινος, PLAT. <i>Tim. 87</i> c, <i>ou</i> περί τινα, LYCURG. <i>162, 27,</i> faire cas de qqn <i>ou</i> de qqe ch. ; λόγον τινὸς οὐκ ἔχειν οὐδένα, ESCHL. <i>Pr. 231 ;</i> οὐδένα λόγον ποιεῖσθαί τινος, HDT. <i>1, 4, etc. ;</i> ἐν οὐδενὶ λόγῳ ποιεῖσθαί τινα, HDT. <i>3, 30,</i> ne faire aucun cas de qqn ;<br><b>      3</b> <i>p. suite :</i> compte qu’on fait de qqn <i>ou</i> de qqe ch., valeur qu’on leur attribue, <i>avec un gén. déterminatif :</i> ἐν ἀνδρὸς λόγῳ εἶναι, HDT. <i>3, 120,</i> être considéré comme un homme de haut rang ; ἐν ἀνδραπόδων λόγῳ ποιεύμενος, HDT. <i>3, 125,</i> considéré <i>ou</i> traité à l’égal d’esclaves ; <i>p. ext</i>. évaluation, <i>en gén. :</i> ὑπὸ τὸν λόγον ἄγειν τι, POL. <i>15, 34, 2,</i> soumettre qqe ch. à l’évaluation, en faire le calcul ;<br><b>      4</b> relation, proportion, analogie : ἀνὰ τὸν αὐτὸν λόγον, PLAT. <i>Phæd. 110</i> d ; εἰς τὸν αὐτὸν λόγον, PLAT. <i>Rsp. 353</i> d ; κατὰ τὸν αὐτὸν λόγον, HDT. <i>1, 186,</i> selon la même évaluation, dans la même proportion ; πρὸς λόγον τινός, ESCHL. <i>Sept. 519 ;</i> ἀνὰ λόγον τινός, PLAT. <i>Tim. 29</i> c, <i>ou</i> τινί, PLAT. <i>2 Alc. 145</i> d (<i>cf</i>. ἀνάλογος) ; κατὰ λόγον τινός, HDT. <i>1, 134, etc</i>. eu égard à, relativement à, proportionnellement à qqe ch. ; κατὰ λόγον τῆς δυνάμεως, XÉN. <i>Cyr. 8, 6, 11,</i> en raison de leur puissance ; <i>t. de gr</i>. τῷ λόγῳ τῶν μετοχικῶν, GRAMM. <i>p. 1393 Bekker, Anecdota græca,</i> par analogie avec les participes ;<br><b>   V</b> compte-rendu, justification, explication : λόγον ἑαυτῷ διδόναι περί τινος, HDT. <i>1, 97,</i> se rendre compte de qqe ch. ; <i>avec</i> ὅτι, HDT. <i>6, 86 ; ou</i> ὡς, HDT. <i>4, 102 ;</i> PLAT. <i>Phæd. 95</i> d, <i>etc</i>. se rendre compte que ; αἰτεῖν, ATT. (PLAT. <i>Pol. 285</i> e, <i>etc.), ou</i> ἀπαιτεῖν περί τινος, ATT. (DÉM. <i>868, 5, etc</i>.) demander compte à qqn, se faire rendre compte par qqn ; λόγον διδόναι τινός, HDT. <i>3, 143 ;</i> ATT. ; <i>ou</i> παρέχειν PLAT. <i>Rsp. 344</i> d, rendre raison, rendre compte de qqe ch. ; λόγον δοῦναι καὶ δέξασθαι, PLAT. <i>Prot. 336</i> c, rendre compte et recevoir le compte-rendu de qqe ch. ; λόγον λαμϐάνειν παρά τινος, DÉM. <i>101, 17,</i> recevoir de qqn le compte-rendu (de qqe ch.) ;<br><b>   VI</b> opinion au sujet d’une chose à venir, présomption, attente, HDT. <i>8, 6, etc. ;</i> ἐπὶ τῷ λόγῳ ὥστε, HDT. <i>3, 36,</i> dans l’attente que, <i>etc. ;</i><br><b>   VII</b> <i>postér. au sens philosophique et religieux :</i><br><b>      1</b> <i>au sens philosoph</i>. le λόγος divin, la raison divine, HERM. TR. <i>Poem. 3, 2, 15, etc. ;</i> PLUT. <i>M. 376</i> c, <i>381</i> b, <i>568</i> d, <i>etc. ;</i> PHIL. <i>1, 4, 5, 6, etc. ;</i><br><b>      2</b> <i>au sens religieux,</i> le Verbe divin, NT. <i>Joh. 1, 1, 14 ; 1 Joh. 1, 1 ; Apoc. 19, 13 ;</i> CELS. (ORIG. <i>1, 852</i> a <i>Migne</i>) ; NAZ. <i>2, 424</i> b <i>Migne</i>.<br><span><b>Étym</b>. λέγω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογος - λόγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n331 fois dans 316 versets de 24 livres bibliques (NT)\n<ul>\n<li>Matthieu (32)</li>\n<li>Marc (24)</li>\n<li>Luc (33)</li>\n<li>Jean (40)</li>\n<li>Actes (65)</li>\n<li>Romains (8)</li>\n<li>1 Corinthiens (17)</li>\n<li>2 Corinthiens (9)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (4)</li>\n<li>Philippiens (4)</li>\n<li>Colossiens (7)</li>\n<li>1 Thessaloniciens (9)</li>\n<li>2 Thessaloniciens (5)</li>\n<li>1 Timothée (8)</li>\n<li>2 Timothée (7)</li>\n<li>Tite (5)</li>\n<li>Hébreux (13)</li>\n<li>Jacques (5)</li>\n<li>1 Pierre (6)</li>\n<li>2 Pierre (4)</li>\n<li>1 Jean (6)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (17)</li>\n</ul>\n</td></tr>\n</table>","G3057":"<h1>logche</h1>\n<p>Strong n° 3057 <i>Prononciation [long'-khay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la pointe de métal, le fer de lance</li>\n<li>une lance (une flèche, un trait renforcé de métal)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λόγχη, ης (ἡ) :<br>   I</b> lance <i>ou</i> javeline, <i>particul. :</i><br><b>      1</b> fer de lance <i>ou</i> de javeline, HDT. <i>7, 69 ;</i> XÉN. <i>Hell. 7, 5, 20, etc. ; d’ord. au pl., avec la sign. du sg., p. opp. à</i> la hampe (τὸ ξυστόν, HDT. <i>1, 52, ou</i> ῥάϐδος, XÉN. <i>Cyn. 10, 3 ;</i> SOPH. <i>Tr. 856</i>) ;<br><b>      2</b> <i>p. ext</i>. lance, javeline, BATR. <i>129 ;</i> PD. <i>N. 8, 30, etc. ;</i> XÉN. <i>Eq. 12, 14 ; An. 4, 7, 16, etc. ; particul</i>. lance <i>comme insigne du commandement :</i> ἑπτὰ λόγχαι, SOPH. <i>O.C. 1312,</i> sept lances, celles des sept chefs ;<br><b>      3</b> épée <i>ou</i> poignard, EUR. <i>Hipp. 1375 ;</i><br><b>      4</b> <i>au plur</i>. armes <i>en gén</i>. (arc, javelots, massue) SOPH. <i>Tr. 512 ;</i><br><b>   II</b> troupe d’hommes armés de lances, EUR. <i>Ph. 442</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. λόγχα, PD. <i>l. c. etc. ;</i> SOPH. <i>Tr. 856 ;</i> EUR. <i>Tr. 1318</i>.<br><span><b>Étym</b>. <i>cf. lat</i>. lancea.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λογχη - λόγχη</font>\n<br><br>peut-être un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G3058":"<h1>loidoreo</h1>\n<p>Strong n° 3058 <i>Prononciation [loy-dor-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire des reproches, railler, insulter, accabler d'injures, outrager</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λοιδορέω-ῶ</b>, insulter, injurier, gourmander durement, <i>abs</i>. EUR. <i>Med. 873, etc. ;</i> τινα, PD. <i>O. 9, 40 ;</i> AR. <i>Nub. 1138, etc. ;</i> XÉN. <i>An. 3, 4, 49, etc. ;</i> PLUT. <i>M. 182</i> d, <i>etc. ;</i> τινι, A. LIB. <i>22 ;</i> SPT. <i>2Macc. 12, 14,</i> faire des reproches à qqn ; τι, ARSTT. <i>Nic. 4, 14,</i> adresser qqe reproche <i>ou</i> qqe injure ; <i>avec un acc. de pers. et un pron. neutre :</i> τινὰ πολλὰ λ. EUR. <i>Hel. 1171,</i> faire beaucoup de reproches à qqn ; τινὰ εἴς τι, PLUT. <i>M. 175</i> b, reprocher durement qqe ch. à qqn ; (<i>cf</i>. AR. <i>Eq. 90) ; avec un adj. attrib. :</i> τὴν τύχην λ. τυφλήν, PLUT. <i>M. 98</i> a, reprocher à la fortune d’être aveugle ;<br><b><i>Moy.</i></b> <span>(<i>ao</i>. ἐλοιδορησάμην <i>ou</i> ἐλοιδορήθην)</span> <i>m. sign</i>. AR. <i>Nub. 1353 ;</i> XÉN. <i>Cyr. 1, 4, 9 ;</i> τινι, AR. <i>Pl. 456, Eq. 1400, etc. ;</i> PLAT. <i>Rsp. 395</i> d, <i>Charm. 154</i> a, <i>etc. ; avec prép. :</i> εἴς τινα, LUC. <i>Anach. 22 ;</i> πρός τινα, SPT. <i>Ex. 17, 2,</i> adresser des reproches blessants à qqn ; <i>avec rég. de pers. et de chose :</i> τινι περί τινος, DÉM. <i>558, 6 ;</i> τινί τινος, A. TAT. <i>1, 6,</i> à qqn sur qqe ch. ; περί τινος, AR. <i>Nub. 62, ou</i> εἴς τι, PLUT. <i>Nic. 2, ou</i> ἐπί τινι, XÉN. <i>Ages. 7, 3,</i> au sujet de qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. au sens act</i>. DÉM. <i>1257, 23, etc</i>.<br><span><b>Étym</b>. λοίδορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λοιδορεω - λοιδορέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3059":"<h1>loidoria</h1>\n<p>Strong n° 3059 <i>Prononciation [loy-dor-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>raillerie, insulte, outrage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λοιδορία, ας (ἡ)</b> reproche blessant, injure, THC. <i>2, 84 ;</i> XÉN. <i>Hier. 1, 14 ;</i> AR. <i>Nub. 934, etc. ;</i> DÉM. <i>151, 20 ; 229, 9, etc. ; au pl</i>. LYS. <i>162, 15</i>.<br><span><b>Étym</b>. λοίδορος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λοιδορια - λοιδορία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G3060":"<h1>loidoros</h1>\n<p>Strong n° 3060 <i>Prononciation [loy'-dor-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un railleur, celui qui insulte</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λοίδορος, ος, ον</b>, injurieux, outrageant, EUR. <i>Cycl. 534 ;</i> ANTH. <i>5, 176 ;</i> ὁ λ. PLUT. <i>M. 177</i> d, insulteur ; τὸ λοίδορον, ARSTT. <i>Physiogn. 4, 6 ;</i> PLUT. <i>M. 810</i> d, insulte, outrage.<br><span><b>Étym</b>. <i>inconnue</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λοιδορος - λοίδορος</font>\n<br><br>vient de loidos (malice)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G3061":"<h1>loimos</h1>\n<p>Strong n° 3061 <i>Prononciation [loy'-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pestilence</li>\n<li>peste, fléau, quelqu'un qui est une peste</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λοιμός, οῦ (ὁ) :<br>      1</b> peste, fléau contagieux, IL. <i>1, 61 ;</i> HÉS. <i>O. 241 ;</i> HDT. <i>7, 171, etc. ;</i> ESCHL. <i>Pers. 715, etc. ;</i> SOPH. <i>O.R. 28 ; au pl</i>. PLAT. <i>Conv. 188</i> b ; <i>Leg. 709</i> a, <i>etc. ;</i><br><b>      2</b> <i>fig. en parl. d’une pers</i>. fléau (<i>lat</i>. pestis) DÉM. <i>794, 5 ;</i><br><b>      3</b> <i>adj</i>. qui est un fléau, funeste, <i>en parl. de pers</i>. SPT. <i>1Reg. 10, 27 ; 25, 17 ; joint à</i> πονηρός, SPT. <i>1Reg. 30, 22 ; en parl. de choses,</i> SYMM. <i>Prov. 20, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. λοιμή, SPT. <i>1Reg. 1, 16</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λοιμος - λοιμός</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3062":"<h1>loipos</h1>\n<p>Strong n° 3062 <i>Prononciation [loy-pos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le reste, le restant\n<ol type=\"a\">\n<li>le reste de tout nombre ou classe pris en considération</li>\n<li>avec une certaine distinction et du contraste, le reste, les autres, ceux qui ne font pas partie d'une classe spécifique</li>\n<li>ce qui reste de choses non épuisées</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λοιπός, ή, όν :<br>      1</b> restant, qui reste, PD. <i>O. 1, 97, etc. ;</i> ATT. ; ἡ λοιπὴ ὁδός, XÉN. <i>An. 3, 4, 46,</i> le reste de la route ; αἱ λ. τῶν νεῶν, THC. <i>7, 72,</i> le reste des navires ; <i>particul. en parl. de deux pers. ou de deux choses, p. opp. à</i> θάτερον, CLÉM. <i>Str. p. 787 ;</i> τὸ λοιπόν <i>ou</i> τὰ λοιπά, ATT. le reste ; καὶ τὰ λοιπά, PLUT. <i>M. 1084</i> c ; HERMOG. <i>Rhet. 278, 1 ;</i> SEXT. <i>629, 17 Bkk</i>. et ainsi du reste, et cætera ; <i>pour marquer une suite dans le raisonnement,</i> et maintenant, maintenant donc, donc : καθεύδετε τὸ λοιπὸν καὶ ἀναπαύεσθε, NT. <i>Matth. 26, 45 ;</i> καθεύδετε λοιπὸν καὶ ἀναπαύεσθε, NT. <i>Marc. 14, 41,</i> et maintenant dormez et reposez-vous ; <i>cf</i>. λοιπόν, POL. <i>1, 15, 11 ;</i> καὶ τὸ λοιπόν, POL. <i>3, 96, 14, etc. ;</i> οἱ λοιποί, ceux qui restent, <i>càd</i>. les descendants, la postérité, PD. <i>I. 3, 57 ;</i> λοιπόν ἐστι, <i>ou simpl</i>. λοιπόν, <i>avec l’inf</i>. il reste (à montrer, à dire, <i>etc</i>.) XÉN. <i>Conv. 4, 1, etc. ; avec l’art</i>. τὸ λοιπὸν ἤδη ἡμῖν ἐστι σκέψασθαι πότερον, PLAT. <i>Rsp. 444</i> e, il nous reste à examiner laquelle des deux choses… ; λοιπὸν οὖν ἐστιν οὐδὲν ἄλλο πλήν <i>avec l’inf</i>. ISOCR. <i>250</i> e, il ne reste donc qu’à, <i>etc. ;</i> τί λοιπὸν ἔσται ἤν ; <i>etc</i>. ISOCR. <i>93</i> e, que restera-t-il (à dire) si, <i>etc. ? abs</i>. ὃ δὲ λοιπόν, ESCHL. <i>Ag. 1572,</i> ce qui reste ; <i>cf</i>. ESCHL. <i>Pr. 684 ;</i> λοιπόν <i>ou</i> τὸ λοιπόν, PLAT. <i>Prot. 321</i> b, du reste ;<br><b>      2</b> <i>particul. avec idée de temps :</i> ὁ λοιπὸς χρόνος, ATT. <i>ou</i> ὁ λοιπὸς τοῦ χρόνου, DÉM. <i>195, 6,</i> l’avenir ; τὸ λοιπὸν τῆς ἡμέρας, XÉN. <i>An. 3, 4, 16,</i> le reste du jour ; <i>d’où adv</i>. τοῦ λοιποῦ χρόνου, SOPH. <i>El. 817 ;</i> ἐκ τοῦ λοιποῦ χρόνου, DÉM. <i>1360, 23 ;</i> ἐκ τοῦ λοιποῦ, XÉN. <i>Conv. 4, 56 ; Hell. 3, 4, 9 ;</i> τὸν λοιπὸν χρόνον, SOPH. <i>Ph. 84 ;</i> εἰς τὸν λοιπὸν χρόνον, PLAT. <i>Ep. 358</i> b ; <i>ou (s.-e</i>. χρόνος) τοῦ λοιποῦ, HDT. <i>2, 109 ;</i> AR. <i>Pax 1084 ;</i> τὸ λοιπόν, PD. <i>P. 5, 118, etc. ;</i> ATT. ; τὰ λοιπά, XÉN. <i>Hell. 1, 1, 27 ;</i> PLAT. <i>Tim. 27</i> b, <i>etc</i>. à l’avenir, désormais, dorénavant.<br><span><b>Étym</b>. λείπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λοιπος - λοιπός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n41 fois dans 41 versets de 14 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (6)</li>\n<li>Actes (5)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (4)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (2)</li>\n<li>Philippiens (2)</li>\n<li>1 Thessaloniciens (2)</li>\n<li>1 Timothée (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G3063":"<h1>loipon</h1>\n<p>Strong n° 3063 <i>Prononciation [loy-pon']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le restant, le reste\n<ol type=\"a\">\n<li>dorénavant, désormais, pour le futur</li>\n<li>enfin, déjà</li>\n<li>pour le reste, en outre, de plus</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λοιπός, ή, όν :<br>      1</b> restant, qui reste, PD. <i>O. 1, 97, etc. ;</i> ATT. ; ἡ λοιπὴ ὁδός, XÉN. <i>An. 3, 4, 46,</i> le reste de la route ; αἱ λ. τῶν νεῶν, THC. <i>7, 72,</i> le reste des navires ; <i>particul. en parl. de deux pers. ou de deux choses, p. opp. à</i> θάτερον, CLÉM. <i>Str. p. 787 ;</i> τὸ λοιπόν <i>ou</i> τὰ λοιπά, ATT. le reste ; καὶ τὰ λοιπά, PLUT. <i>M. 1084</i> c ; HERMOG. <i>Rhet. 278, 1 ;</i> SEXT. <i>629, 17 Bkk</i>. et ainsi du reste, et cætera ; <i>pour marquer une suite dans le raisonnement,</i> et maintenant, maintenant donc, donc : καθεύδετε τὸ λοιπὸν καὶ ἀναπαύεσθε, NT. <i>Matth. 26, 45 ;</i> καθεύδετε λοιπὸν καὶ ἀναπαύεσθε, NT. <i>Marc. 14, 41,</i> et maintenant dormez et reposez-vous ; <i>cf</i>. λοιπόν, POL. <i>1, 15, 11 ;</i> καὶ τὸ λοιπόν, POL. <i>3, 96, 14, etc. ;</i> οἱ λοιποί, ceux qui restent, <i>càd</i>. les descendants, la postérité, PD. <i>I. 3, 57 ;</i> λοιπόν ἐστι, <i>ou simpl</i>. λοιπόν, <i>avec l’inf</i>. il reste (à montrer, à dire, <i>etc</i>.) XÉN. <i>Conv. 4, 1, etc. ; avec l’art</i>. τὸ λοιπὸν ἤδη ἡμῖν ἐστι σκέψασθαι πότερον, PLAT. <i>Rsp. 444</i> e, il nous reste à examiner laquelle des deux choses… ; λοιπὸν οὖν ἐστιν οὐδὲν ἄλλο πλήν <i>avec l’inf</i>. ISOCR. <i>250</i> e, il ne reste donc qu’à, <i>etc. ;</i> τί λοιπὸν ἔσται ἤν ; <i>etc</i>. ISOCR. <i>93</i> e, que restera-t-il (à dire) si, <i>etc. ? abs</i>. ὃ δὲ λοιπόν, ESCHL. <i>Ag. 1572,</i> ce qui reste ; <i>cf</i>. ESCHL. <i>Pr. 684 ;</i> λοιπόν <i>ou</i> τὸ λοιπόν, PLAT. <i>Prot. 321</i> b, du reste ;<br><b>      2</b> <i>particul. avec idée de temps :</i> ὁ λοιπὸς χρόνος, ATT. <i>ou</i> ὁ λοιπὸς τοῦ χρόνου, DÉM. <i>195, 6,</i> l’avenir ; τὸ λοιπὸν τῆς ἡμέρας, XÉN. <i>An. 3, 4, 16,</i> le reste du jour ; <i>d’où adv</i>. τοῦ λοιποῦ χρόνου, SOPH. <i>El. 817 ;</i> ἐκ τοῦ λοιποῦ χρόνου, DÉM. <i>1360, 23 ;</i> ἐκ τοῦ λοιποῦ, XÉN. <i>Conv. 4, 56 ; Hell. 3, 4, 9 ;</i> τὸν λοιπὸν χρόνον, SOPH. <i>Ph. 84 ;</i> εἰς τὸν λοιπὸν χρόνον, PLAT. <i>Ep. 358</i> b ; <i>ou (s.-e</i>. χρόνος) τοῦ λοιποῦ, HDT. <i>2, 109 ;</i> AR. <i>Pax 1084 ;</i> τὸ λοιπόν, PD. <i>P. 5, 118, etc. ;</i> ATT. ; τὰ λοιπά, XÉN. <i>Hell. 1, 1, 27 ;</i> PLAT. <i>Tim. 27</i> b, <i>etc</i>. à l’avenir, désormais, dorénavant.<br><span><b>Étym</b>. λείπω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λοιπον - λοιπόν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Actes (1)</li>\n<li>1 Corinthiens (3)</li>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>2 Thessaloniciens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3064":"<h1>loipou</h1>\n<p>Strong n° 3064 <i>Prononciation [loy-poo']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dorénavant, désormais, au reste, pour le futur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λοιπου - λοιποῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G3065":"<h1>Loukas</h1>\n<p>Strong n° 3065 <i>Prononciation [loo-kas']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Luc (Angl. Luke ou Lucus) = « qui donne la lumière »\n<ol><li>un Chrétien Gentil, le compagnon de Paul pour la prédication de l'évangile pendant de nombreux voyages ; il était médecin, et l'auteur du livre de Luc et du livre des Actes dans le N.T.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λουκᾶς, ᾶ (ὁ)</b> saint Luc, <i>un des quatre évangélistes,</i> NT. <i>2Tim. 4, 11, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λυκας - Λουκᾶς</font>\n<br><br>contraction du Latin 'Lucanus'</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Colossiens (1)</li>\n<li>2 Timothée (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G3066":"<h1>Loukios</h1>\n<p>Strong n° 3066 <i>Prononciation [loo'-kee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lucius = « lumière, vif, brillant, blanc »\n<ol>\n<li>un homme venant de Cyrène, qui fut prophète et enseignant dans l'église d'Antioche (<a class=\"ref\" data-r=\"ACT13.1\">Actes 13.1</a>) et peut-être le même que celui mentionné dans <a class=\"ref\" data-r=\"ROM16.21\">Romains 16.21</a></li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λούκιος, ου (ὁ)</b> = <i>lat</i>. Lucius, <i>n. d’h. rom</i>. ANTH. <i>11, 15 ;</i> LUC. <i>As. 2, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λουκιος - Λούκιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G3067":"<h1>loutron</h1>\n<p>Strong n° 3067 <i>Prononciation [loo-tron']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>baignade, bain, l'action de baigner</li>\n<li>bain (de la fiancée avant le mariage), de la régénération</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λουτρόν, οῦ (τὸ) :<br>      1</b> bain, endroit où l’on se baigne, salle de bain : γυμνάσια καὶ λουτρά, XÉN. <i>Ath. 2, 10,</i> des gymnases et des bains ;<br><b>      2</b> bain, eau pour se baigner, <i>dans Hom. touj. au pl. :</i> θερμὰ λουτρά, IL. <i>14, 6, etc. ;</i> PD. <i>O. 12, 21, etc</i>. bains chauds ; <i>au sg</i>. HÉS. <i>O. 751 ;</i> ESCHL. <i>fr. 332 ;</i> SOPH. <i>Ant. 1201, etc. ;</i><br><b>      3</b> action de se baigner, HDT. <i>6, 52 ;</i> λουτροῖς χρῆσθαι, XÉN. <i>Cyr. 7, 5, 20,</i> prendre des bains ;<br><b>      4</b> <i>par ext</i>. eau lustrale pour les purifications, SOPH. <i>El. 84, 434 ;</i> EUR. <i>Ph. 1667 ; t. eccl</i>. eau du baptême, NT. <i>Eph. 5, 26 ; Tit. 3, 5</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans l’</i>IL. <i>et l’</i>OD. λοετρόν ; <i>mais</i> λουτρόν <i>dans</i> HH. <i>Cer. 50 ;</i> HÉS. <i>O. 751</i>.<br><span><b>Étym</b>. λούω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λουτρον - λουτρόν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Ephésiens (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G3068":"<h1>louo</h1>\n<p>Strong n° 3068 <i>Prononciation [loo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>baigner, laver\n<ol type=\"a\">\n<li>une personne morte</li>\n<li>laver pour nettoyer le sang des blessures</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λούω</b> <span>(<i>impf</i>. ἔλουον, <i>f</i>. λούσω, <i>ao</i>. ἔλουσα, <i>pf. inus. ; pass. ao</i>. ἐλούθην, <i>réc</i>. ἐλούσθην, <i>pf</i>. λέλουμαι, <i>réc</i>. λέλουσμαι)</span> laver, <i>particul. :</i><br><b>      1</b> laver le corps, baigner, faire prendre un bain, <i>p. opp. à</i> νίζω, laver les pieds et les mains, <i>ou à</i> πλύνω, laver des vêtements (<i>ttf</i>. λούω, <i>au sens de</i> πλύνω, IL. <i>23, 282</i>) : τινά, IL. <i>5, 905 ;</i> OD. <i>4, 49,</i> baigner qqn ; ἐν ποταμῷ, OD. <i>6, 210,</i> faire prendre un bain dans un fleuve ;<br><b>      2</b> laver, <i>en gén. :</i> λοῦσαι νεκρόν, HDT. <i>2, 86 ;</i> SOPH. <i>Ant. 901 ;</i> EUR. <i>Tr. 1152,</i> laver un mort ;<br><b>      3</b> <i>p. ext</i>. mouiller : λοῦσθαι ὑπὸ τοῦ Διός, HDT. <i>3, 124, 125,</i> être mouillé par la pluie ;<br><b>      4</b> <i>t. eccl</i>. plonger dans l’eau, baptiser, CELS. (ORIG. <i>1, 736 Migne</i>) ; CLÉM. <i>1, 996 Migne, etc. ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> se baigner : ἐν βαλανείῳ, PLAT. <i>Rsp. 495</i> e, dans un fleuve, dans un bain ; <i>avec le dat. sans prép. :</i> ποταμοῖο ῥοῇσιν, OD. <i>6, 216,</i> dans le courant d’un fleuve ; <i>avec gén. seul. ou précédé d’une prép. :</i> ποταμοῖο, IL. <i>6, 508,</i> dans un fleuve ; Ὠκεανοῖο, IL. <i>5, 6,</i> dans l’Océan, <i>en parl. d’une constellation ;</i> ἀπὸ κρήνης, HDT. <i>3, 23 ;</i> CALL. <i>Del. 124,</i> dans une fontaine ; εἰς λουτρῶνας, ATH. <i>438</i> e, aller se baigner dans une piscine ; <i>rar. avec l’acc. de la partie baignée ;</i> χρόα, HÉS. <i>O. 520, Th. 5,</i> se baigner le corps (<i>cf</i>. λοῦσθαι ὕδωρ τὸ σῶμα, HDT. <i>4, 75</i>) ;<br><b>      2</b> se mouiller : αἵματι λούεσθαι, ANTH. <i>6, 2 ;</i> CALL. <i>Del. 95,</i> s’inonder de sang ; λελουμένος τῷ φόνῳ, LUC. <i>D. mer. 13, 3,</i> inondé du sang d’un meurtre.<br><span><b><span class=\"arrow\"></span></b> <i>Act. impf. 3 sg</i>. ἔλουε (<i>var</i>. ἔλου) LUC. <i>Nec. 7. — Pass. prés. 3 pl. contr</i>. λοῦνται, HDT. <i>1, 198 ; 2, 37 ;</i> XÉN. <i>Cyr. 1, 3, 11 ; inf. contr</i>. λοῦσθαι, OD. <i>6, 216 ;</i> HDT. <i>3, 124 ;</i> PLAT. <i>Leg. 942</i> b ; <i>part. contr</i>. λούμενος (<i>var</i>. λουόμενος) HDT. <i>3, 23 ;</i> XÉN. <i>Mem. 3, 13, 3. Impf. 3 pl. contr</i>. ἐλοῦντο, HDT. <i>3, 125 ;</i> XÉN. <i>Cyr. 4, 5, 4. Ao. 3 pl. poét</i>. λούσαντο, OD. <i>4, 48</i>.<br><span><b>Étym</b>. <i>p</i>. *λόϝω, <i>de la R. indo-europ</i>. *leuh₃-, laver, baigner ; <i>cf</i>. λοέω, <i>lat</i>. lavāre, lautus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λουω - λούω</font>\n<br><br>un verbe racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Actes (2)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3069":"<h1>Ludda</h1>\n<p>Strong n° 3069 <i>Prononciation [lud'-dah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lydde (Angl. Lydda) = « lutte »\n<ol><li>ville à environ 15 km de Joppé, et la première ville sur la route la plus au nord des deux routes entre Joppé et Jérusalem</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λυδδα - Λύδδα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G3070":"<h1>Ludia</h1>\n<p>Strong n° 3070 <i>Prononciation [loo-dee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lydie (Angl. Lydia) = « travail »\n<ol><li>femme originaire de Thyatire, vendeuse de pourpre, première Européenne convertie par Paul, puis ensuite son hôtesse pendant son premier séjour à Philippes</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λυδία, ας (ἡ)</b> <i>v</i>. Λύδιος.<br><br>\n<b>Λύδιος, α, ον</b> <span>[ῡ]</span> de Lydie, PD. <i>N. 4, 45, etc. ;</i> ESCHL. <i>Suppl. 550 ;</i> SOPH. <i>Tr. 432 ;</i> XÉN. <i>An. 1, 5, 6, etc. ;</i> Λυδία λίθος, BACCHYL. <i>fr. 14, 1, ou</i> Λυδίη πέτρη, THCR. <i>Idyl. 12, 36,</i> pierre lydienne, <i>càd</i>. pierre de touche pour éprouver l’or ; <i>subst</i>. ἡ Λυδία (<i>s.-e</i>. γῆ <i>ou</i> χώρα) la Lydie, <i>contrée d’Asie Mineure,</i> XÉN. <i>Cyr. 6, 1, 25, etc. ; An. 1, 2, 5, etc. ;</i> DÉM. <i>23, 155 Baiter-Sauppe, etc. ; ion</i>. Λυδίη, HDT. <i>1, 79, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fém</i>. -ος, PD. <i>N. 4, 45 ;</i> LUC. <i>V.H. 1, 8, etc</i>.<br><span><b>Étym</b>. Λυδός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λυδια - Λυδία</font>\n<br><br>féminin de Ludios (mot d'origine étrangère) (un Lydien, en Asie Mineure occidentale, capitale : Sardes)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G3071":"<h1>Lukaonia</h1>\n<p>Strong n° 3071 <i>Prononciation [loo-kah-on-ee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lycaonie = « terre du loup »\n<ol><li>région d'Asie Mineure, située entre Pisidie, Cilicie, Cappadoce, Galatie et Phrygie, dont les villes principales étaient Derbe, Lystre et Icone. Contrée du plateau anatolien.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λυκαονία, ας (ἡ)</b> <span>[ῠκᾱ]</span> Lycaonie, <i>contrée d’Asie Mineure,</i> XÉN. <i>An. 1, 2, 19, etc. ;</i> PLUT. <i>Luc. 23, etc</i>.<br><span><b>Étym</b>. Λυκάων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυκαονια - Λυκαονία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3072":"<h1>Lukaonisti</h1>\n<p>Strong n° 3072 <i>Prononciation [loo-kah-on-is-tee']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dans des paroles ou une langue de la Lycaonie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λυκαονιστί</b> <span>[ῠᾱ]</span> <i>adv</i>., à la manière des Lycaoniens, NT. <i>Ap. 14, 11</i>.<br><span><b>Étym</b>. Λυκάων.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λυκαονιστι - Λυκαονιστί</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3073":"<h1>Lukia</h1>\n<p>Strong n° 3073 <i>Prononciation [loo-kee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lycie = « de loup »\n<ol><li>région montagneuse d'Asie Mineure, entourée par la Pamphylie, Phrygie, Carie, et la Mer Méditerranée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λυκία, ας (ἡ)</b> <span>[ῠ]</span> Lycie, <i>contrée d’Asie Mineure,</i> IL. <i>2, 824 ; 5, 172 ;</i> HDT. <i>1, 173 ; 7, 92 ;</i> PD. <i>O. 13, 58 ;</i> THC. <i>8, 41 ;</i> EUR. <i>Alc. 112</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et épq</i>. Λυκίη, IL. HDT. <i>ll. cc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λυκια - Λυκία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3074":"<h1>lukos</h1>\n<p>Strong n° 3074 <i>Prononciation [loo'-kos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un loup</li>\n<li>métaph. des hommes cruels, gourmands, rapaces, destructeurs</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λύκος, ου</b> <span>[ῠ]</span><br><b>   I (ὁ, ἡ)</b> loup, louve, IL. <i>4, 471 ; 10, 334, etc. ;</i> OD. <i>10, 212 ;</i> PD. <i>P. 2, 84 ;</i> PLUT. <i>M. 280</i> c, <i>etc. ; proverb. pour parler de choses impossibles :</i> λύκος οἶν ὑμεναιοῖ, AR. <i>Pax 1076, 1112,</i> un loup s’unit à une brebis ; λύκοι ἄρν' ἀγαπῶσιν, POÈT. (PLAT. <i>Phædr. 241</i> d) le loup est l’ami de l’agneau ; ἐκ λύκου στόματος σῴζεσθαι, PARŒM. se tirer sain et sauf de la gueule d’un loup ; <i>pour parler d’attente vaine :</i> λύκος κεχηνώς, AR. <i>Lys. 629,</i> loup qui reste la gueule béante ; λύκον ἰδεῖν, PLAT. <i>Rsp. 336</i> d ; THCR. <i>Idyl. 14, 22,</i> avoir vu le loup, <i>càd</i>. rester muet, <i>parce que, dans la croyance populaire, si le premier objet qu’on avait vu était un loup, on était frappé de mutisme ;</i><br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> esturgeon, <i>poisson,</i> ATH. <i>282</i> d ; GEOP. <i>18, 14, 1 ;</i><br><b>      2</b> araignée-loup, <i>insecte,</i> ARSTT. <i>H.A. 9, 39, 1 ;</i> NIC. <i>Th. 734 ;</i><br><b>      3</b> sorte de geai, ARSTT. <i>H.A. 9, 24 ;</i><br><b>      4</b> fleur de l’iris, PHILIN. (ATH. <i>682</i> a) ;<br><b>      5</b> pilule contre la dysenterie, AÉT. <i>9 ;</i><br><b>      6</b> orobanche, DIOSC. <i>2, 171 ;</i><br><b>      7</b> <i>sobriquet des débauchés,</i> ANTH. <i>12, 250 ;</i><br><b>      8</b> mors très rude pour les chevaux dont la bouche est dure (<i>cf. lat</i>. lupatum) PLUT. <i>M. 641</i> f ;<br><b>      9</b> sorte de lien <i>ou</i> de nœud, HIPPIATR. <i>2, 74 ;</i> GAL. <i>4, 468, etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *ulk<sup>w</sup>o-, loup <i>avec métath. ; cf. lat</i>. lupus, <i>sscr</i>. vŕ̥ka-.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυκος - λύκος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>Jean (2)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3075":"<h1>lumainomai</h1>\n<p>Strong n° 3075 <i>Prononciation [loo-mah'-ee-nom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>apposer un stigmate, déshonorer, tacher, souiller</li>\n<li>traiter honteusement ou avec préjudice, maltraiter, ravager, dévaster, ruiner</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λυμαίνω</b> <span>[ῡ]</span><br><b>   I</b> (<i>act. seul. ao</i>. ἐλύμηνα <i>forme réc</i>.) endommager, souiller, LIB. <i>4, p. 350, 19 ; au pass</i>. être maltraité : δεδεμένος καὶ λυμαινόμενος, ANT. <i>136, 43,</i> lié et maltraité ; <i>cf</i>. ESCHL. <i>Ch. 290, etc. ;</i> se gâter, ἃ οὔτε κατασήπεται οὔτε λυμαίνεται, XÉN. <i>Cyr. 8, 2, 22,</i> ce qui ne se pourrit ni ne se corrompt ;<br><b>   II</b> <b><i>Moy</i>. λυμαίνομαι</b> <span>(<i>fut</i>. λυμανοῦμαι, <i>ao</i>. ἐλυμηνάμην)</span><br><b>   I</b> endommager, <i>d’où :</i><br><b>      1</b> souiller, gâter, corrompre : νόσος λ. τὸ σῶμα, HPC. <i>307, 28,</i> la maladie détériore le corps ; <i>fig</i>. τὰ λέχη, EUR. <i>Bacch. 354,</i> souiller la couche ; λ. νόμους, LYS. <i>185, 40,</i> violer les lois ;<br><b>      2</b> ruiner, détruire : ὅσα μετ' ἐλπίδων λυμαίνεται, THC. <i>5, 103,</i> tout ce qui est détruit avec nos espérances ;<br><b>      3</b> maltraiter, traiter indignement, <i>acc. :</i> λύμῃσι ἀνηκέστοισι λυμαίνεσθαί τινα, HDT. <i>6, 12,</i> infliger à qqn le plus indigne traitement ; <i>cf</i>. HDT. <i>5, 33 ; 8, 28 ; dat</i>. λ. νεκρῷ, HDT. <i>1, 214,</i> faire subir à un mort d’indignes traitements ; <i>cf</i>. ISOCR. <i>397</i> b ; DÉM. <i>326 fin, etc. ; avec un adj. neutre :</i> πάντα λυμαίνεσθαι, HDT. <i>3, 16,</i> infliger tous les mauvais traitements possibles ; <i>avec double rég. :</i> τινὶ τάδε λ. EUR. <i>Bacch. 632,</i> infliger à qqn de tels traitements ; <i>particul. avec double acc. :</i> λύμην τινὰ λυμαίνεσθαι, EUR. <i>Hel. 1099 ; cf</i>. AR. <i>Av. 100 ;</i><br><b>   II</b> purifier, laver, nettoyer, HPC. <i>Diæt. 1, 13</i>.<br><span><b>Étym</b>. λύμη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυμαινομαι - λυμαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3076":"<h1>lupeo</h1>\n<p>Strong n° 3076 <i>Prononciation [loo-peh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rendre affligé</li>\n<li>affecter de tristesse, jeter dans la douleur</li>\n<li>chagriner, offenser</li>\n<li>faire que quelqu'un soit gêné, lui causer un scrupule</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λυπέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao. inus., pf</i>. λελύπηκα)</span> <span>[ῡ]</span><br><b>      1</b> chagriner, affliger : τινα, HDT. <i>7, 190 ; 8, 144 ;</i> SOPH. <i>El. 59, etc. ;</i> EUR. <i>Ion 1311, etc</i>. qqn ; <i>p. opp. à</i> εὐφραίνειν, EUR. <i>Alc. 238, ou à</i> χαίρειν, ESCHL. <i>fr. 257 ; avec un neutre :</i> λ. μηδέν τινα, EUR. <i>Cycl. 338,</i> ne causer aucun chagrin à qqn ; <i>cf</i>. PLAT. <i>Ap. 41</i> e ; <i>avec un part. :</i> ἐλύπει αὐτὸν ἡ χώρα πορθουμένη, XÉN. <i>An. 7, 7, 12,</i> ce qui le chagrinait, c’était de voir le pays dévasté ; <i>ou un relat</i>. SOPH. <i>O.R. 74 ; au pass</i>. λυπεῖσθαι φρένα, THGN. <i>593,</i> être chagriné, affligé, ennuyé : τὰς ἐσχάτας λύπας λ. PLAT. <i>Gorg. 494</i> a, éprouver un chagrin extrême ; λ. τι, SOPH. <i>Aj. 1086 ;</i> πρός τι, THC. <i>2, 64 ;</i> διά τι, XÉN. <i>Cyr. 8, 3, 41 ;</i> PLAT. <i>Phil. 52</i> b ; ἐπί τινι, XÉN. <i>Hier. 1, 5 ; Mem. 3, 9, 8 ;</i> περί τινος, PLAT. <i>Prot. 354</i> d, <i>etc</i>. s’affliger de qqe ch. ; <i>avec un part. :</i> ἐλυπεῖτο ὁρῶν, DÉM. <i>301, 3,</i> il s’affligeait de voir ; <i>cf</i>. EUR. <i>Med. 286 ;</i><br><b>      2</b> vexer, taquiner : λυπεῖσθαι ὑπὸ θεραπαίνης ἐπίτηδες, LYS. <i>92, 37,</i> être taquiné à dessein par une servante ;<br><b>      3</b> incommoder, gêner : ὁ θώραξ λυπεῖ, XÉN. <i>Mem. 3, 10, 15,</i> la cuirasse incommode (par son poids) ; λ. τινα, XÉN. <i>An. 2, 3, 23,</i> gêner qqn ; <i>abs</i>. SOPH. <i>Aj. 589, etc. ;</i><br><b>      4</b> inquiéter, harceler (un ennemi) HDT. <i>9, 40 ;</i> THC. <i>6, 66 ; en parl. d’incursions,</i> THC. <i>4, 53 ;</i><br><b>      5</b> faire du tort, nuire : οὐδὲν ἐλύπησεν ὥστε μὴ οὐχί, PLAT. <i>Crat. 393</i> e, cela ne fit pas tort au point de ne pas, cela n’empêcha pas de, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Prés. part. fém. ion</i>. λυπεῦσα, HDT. <i>7, 190 ; plur. masc</i>. λυπέοντες, HDT. <i>8, 144. Act. impf. 3 sg. ion</i>. ἐλύπεε, HDT. <i>9, 61. — Pass. opt. 3 pl. ion</i>. λυποίατο, HDT. <i>1, 99. — Fut. moy. au sens pass</i>. λυπήσομαι, EUR. <i>Med. 474, etc</i>.<br><span><b>Étym</b>. λύπη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυπεω - λυπέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n26 fois dans 21 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (2)</li>\n<li>Jean (2)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (12)</li>\n<li>Ephésiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3077":"<h1>lupe</h1>\n<p>Strong n° 3077 <i>Prononciation [loo'-pay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>douleur, peine, chagrin, contrariété, affliction\n<ol type=\"a\">\n<li>de personnes en deuil</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λύπη, ης (ἡ)</b> <span>[ῡ]</span><br><b>      1</b> peine, <i>p. opp. à</i> ἡδονή, PLAT. <i>Phil. 31</i> c, <i>etc., d’où</i> chagrin, tristesse, affliction, ESCHL. <i>Ag. 791, etc. ;</i> SOPH. <i>Ph. 67, etc. ;</i> PLAT. <i>Tim. 42</i> a, <i>etc. ; p. opp. à</i> χαρά, XÉN. <i>Hell. 7, 1, 32 ;</i> λύπην τινὶ ἐμϐάλλειν, ANT. <i>116, 29, ou</i> φέρειν, AND. <i>20, 35,</i> causer du chagrin à qqn ;<br><b>      2</b> situation <i>ou</i> condition pénible, HDT. <i>7, 152 ;</i><br><b>      3</b> douleur physique, <i>particul</i>. douleurs de l’enfantement, SOPH. <i>El. 533</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. λύπα, EUR. <i>Hel. 1344</i>.<br><span><b>Étym</b>. <i>p.-ê. R. indo-europ</i>. *leup-, peler.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυπη - λύπη</font>\n<br><br>apparemment un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 14 versets de 7 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (4)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (6)</li>\n<li>Philippiens (2)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3078":"<h1>Lusanias</h1>\n<p>Strong n° 3078 <i>Prononciation [loo-san-ee'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lysanias = « qui chasse au loin la peine »\n<ol><li>un tétrarque d'Abilène (district autour d'Abila) dans la treizième année de Tibère (29 ap. J.C.), du temps où Hérode Antipas était tétrarque de Galilée, Hérode Philippe tétrarque d'Iturée et Trachonite.</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λυσ·ανίας, ου (ὁ)</b> Lysanias, <i>h</i>. PLAT. <i>Ap. 33</i> e.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. -ίης, HDT. <i>6, 127 ;</i> CALL. <i>Ep. 30, 5</i>.<br><span><b>Étym</b>. <i>v</i>. λυσανίας.</span><br><br>\n<b>λυσ·ανίας, ου</b> <span>[ῡᾰᾱ]</span> <i>adj. m</i>. qui dissipe le chagrin, AR. <i>Nub. 1162</i>.<br><span><b>Étym</b>. λ. ἀνία.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λυσανιας - Λυσανίας</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3079":"<h1>Lusias</h1>\n<p>Strong n° 3079 <i>Prononciation [loo-see'-as]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lysias = « libérateur »\n<ol><li>un tribun militaire ou chiliarque (chef de 1000 soldats) d'une cohorte romaine, commandant la garnison de Jérusalem</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Λυσίας, ου (ὁ)</b> Lysias :<br><b>      1</b> <i>célèbre orateur athénien ;</i><br><b>      2</b> <i>général athénien,</i> XÉN. <i>Hell. 1, 6, 30, etc. ;</i><br><b>      3</b> <i>autres,</i> Ps.-PLUT. <i>Mus. 2, 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dès le 6<sup>e</sup> siècle av. J.C. l’orthogr. att. flotte entre les formes</i> Λυσίας <i>et</i> Λυσέας, <i>v. Meisterh. p. 90</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λυσιας - Λυσίας</font>\n<br><br>affinité incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G3080":"<h1>lusis</h1>\n<p>Strong n° 3080 <i>Prononciation [loo'-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>relâcher, rendre libre\n<ol type=\"a\">\n<li>un prisonnier</li>\n<li>des liens du mariage, divorcer, séparation</li>\n</ol>\n</li>\n<li>libérer, rançonner, délivrer\n<ol type=\"a\">\n<li>liquidation d'une dette</li>\n</ol>\n</li>\n<li>moyens ou pouvoir de libération</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λύσις, εως (ἡ)</b> <span>[ῠ]</span><br><b>   I</b> action de délier : τῶν δεσμῶν, PLAT. <i>Rsp. 532</i> b, <i>ou</i> ἀπὸ τῶν δεσμῶν, PLAT. <i>Rsp. 515</i> c, action de délivrer des liens ;<br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> libération, affranchissement : λύσις πρὸς <i>ou</i> εἰς οἶκον, SOPH. <i>El. 573,</i> dénouement permettant aux Grecs de retourner dans leurs foyers ; ἡ λ. τῆς αἰσθήσεως ἐγρήγορσις, ARSTT. <i>Somn. 1, 14,</i> le réveil est l’affranchissement des sens (enchaînés par le sommeil) ; ψυχῆς ἀπὸ σώματος, PLAT. <i>Phæd. 67</i> d, <i>ou simpl</i>. λ. τοῦ σώματος, PLAT. <i>Ax. 371</i> a, affranchissement de l’âme séparée du corps ; <i>avec le gén. de l’objet dont on est affranchi :</i> χρειῶν, HÉS. <i>O. 402,</i> libération <i>ou</i> acquittement de dettes ; κακῶν, PLAT. <i>Phædr. 244</i> e ; νόσου, LUC. <i>H. conscr. 1 ;</i> θανάτου, OD. <i>9, 421, etc. ;</i> δειμάτων, THC. <i>2, 102,</i> délivrance de maux, de la maladie, de la mort, de craintes, <i>etc. ; abs</i>. séparation, divorce, NT. <i>1Cor. 7, 27 ;</i><br><b>      2</b> action de délivrer de la servitude, rançon : νεκροῖο, IL. <i>24, 655,</i> pour un mort ; αἰχμαλώτων, DÉM. <i>107, 14,</i> libération de prisonniers de guerre ;<br><b>      3</b> absolution d’une faute après expiation, SOPH. <i>O.R. 921 ; joint à</i> καθαρμός, PLAT. <i>Phæd. 82</i> d ; <i>au plur. joint à</i> καθαρμοί, PLAT. <i>Rsp. 364</i> e ;<br><b>      4</b> <i>c</i>. κατάλυσις, lieu de halte, de repos : λ. δόρπου, PD. <i>O. 11, 49,</i> lieu où l’on prend le repas (après la lutte) ;<br><b>      5</b> fin, achèvement, <i>p. anal</i>. dénouement d’une tragédie, <i>p. opp. à</i> δέσις, ARSTT. <i>Poet. 15, 16 ; 18, 11, etc. ;</i><br><b>      6</b> solution d’une difficulté, d’une objection, <i>etc</i>. ARSTT. <i>Rhet. 2, 15, 1, etc. ; Nic. 7, 2, 12, etc. ;</i> λ. προϐλήματος, POL. <i>30, 17, 5,</i> solution d’un problème ; <i>p. suite :</i> interprétation : σημείων τεράτων τε λ. ORPH. <i>Arg. 37,</i> des signes et des prodiges ; <i>ou</i> réfutation d’un argument, ARSTT. <i>Rhet. 2, 25, 2, etc. ;</i><br><b>      7</b> relâchement : νεύρων καὶ ὀστέων, HPC. relâchement <i>ou</i> faiblesse des nerfs et des os ; <i>cf</i>. ARSTT. <i>Probl. 27, 3, 2 ; p. anal</i>. adoucissement d’une expression, LGN <i>38 ;</i><br><b>      8</b> dissolution : σφραγίδων, LUC. <i>Alex. 20,</i> rupture de sceaux ; <i>fig</i>. πολιτείας, PLAT. <i>Leg. 945</i> c ; ARSTT. <i>Pol. 2, 8, 17,</i> dissolution d’un État ;<br><b>      9</b> <i>t. de rhét</i>. solution de continuité par absence de copules (<i>p. ex</i>. ἐδεξάμην, ἔτικτον, ἐκτρέφω, pour ἐδεξάμην καὶ, <i>etc</i>.) D. PHAL. <i>194 ; t. de métr</i>. brisement d’une voyelle en deux (<i>par ex. épq</i>. ὁρόω pour ὁρῶ) D. PHAL. <i>70 ; t. de gramm</i>. disjonction en mots distincts des éléments d’un composé (<i>p. ex</i>. σίτου πομπή <i>pour</i> σιτοπομπία) D. PHAL. <i>92</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. épq. et ion</i>. λύσιος, IL. <i>24, 655</i>.<br><span><b>Étym</b>. λύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυσις - λύσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G3081":"<h1>lusitelei</h1>\n<p>Strong n° 3081 <i>Prononciation [loo-sit-el-i']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>acquitter ses impôts</li>\n<li>revenir sur des dépenses</li>\n<li>être utile, avantageux, profitable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λυσιτελέω-ῶ</b> <span>[ῡῐ]</span> <span>(<i>impf</i>. ἐλυσιτέλεον-ουν)</span> être avantageux, être utile : τινι, HDT. <i>1, 97 ;</i> XÉN. <i>Mem. 2, 1, 15 ;</i> PLAT. <i>Prot. 327</i> b, <i>etc</i>. à qqn ; <i>impers</i>. λυσιτελεῖ, ATT. cela est avantageux ; <i>avec un inf</i>. τεθνάναι λυσιτελεῖ ἢ ζῆν, AND. <i>16, 28,</i> il vaut mieux être mort que de vivre ; <i>ou un dat. et un inf. :</i> μοὶ λυσιτελεῖ ὥσπερ ἔχω ἔχειν, PLAT. <i>Ap. 22</i> e, mieux vaut pour moi être comme je suis ; <i>avec un part. :</i> οἷς λυσιτελεῖ πειθομένοις, LYS. <i>174, 14,</i> ceux à qui il est avantageux d’obéir ; <i>cf</i>. PLAT. <i>1 Alc. 113</i> d ; <i>avec une prop. inf</i>. HPC. <i>Fract. 765 ;</i> τὸ λυσιτελοῦν, PLAT. <i>Rsp. 336</i> d ; DÉM. <i>26, 16 ;</i> τὰ λυσιτελοῦντα, THC. <i>6, 85, etc</i>. ce qui est utile, avantageux.<br><span><b>Étym</b>. λυσιτελής.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυσιτελει - λυσιτελέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3082":"<h1>Lustra</h1>\n<p>Strong n° 3082 <i>Prononciation [loos'-trah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lystre (Angl. Lystra) = « qui rançonne, qui rachète »\n<ol><li>cité de la partie orientale de la grande plaine de Lycaonie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυστρα - Λύστρα</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (5)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3083":"<h1>lutron</h1>\n<p>Strong n° 3083 <i>Prononciation [loo'-tron]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>le prix pour un rachat, une rançon\n<ol type=\"a\">\n<li>paiement pour des esclaves, captifs</li>\n<li>pour la rançon de la vie</li>\n</ol>\n</li>\n<li>pour en libérer plusieurs de la misère et des fautes de leurs péchés</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λύτρον, ου (τὸ)</b> moyen de délier, <i>d’où :</i><br><b>      1</b> moyen de délivrance, rançon, <i>particul</i>. prix d’une rançon, <i>d’ord. au pl</i>. HDT. <i>5, 77, etc. ;</i> λύτρα ἀποδιδόναι, DÉM. <i>1250, 2 ; ou</i> καταθεῖναι, DÉM. <i>1250, 18,</i> payer, déposer une rançon ; ἀφιέναι ἄνευ λύτρων, XÉN. <i>Hell. 7, 2, 16,</i> renvoyer sans rançon ; <i>avec un gén. :</i> λύτρα αἰχμαλώτων λαμϐάνειν τὴν γῆν, THC. <i>6, 5,</i> prendre le territoire comme rançon des prisonniers ;<br><b>      2</b> moyen d’expier, <i>gén</i>. PD. <i>O. 7, 77 ;</i> ESCHL. <i>Ch. 48 ;</i><br><b>      3</b> <i>p. suite,</i> compensation, récompense, PD. <i>I. 7, 1</i>.<br><span><b>Étym</b>. λύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυτρον - λύτρον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G3084":"<h1>lutroo</h1>\n<p>Strong n° 3084 <i>Prononciation [loo-tro'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>libérer à la réception d'une rançon</li>\n<li>racheté, libéré par paiement de rançon\n<ol type=\"a\">\n<li>libérer</li>\n<li>racheter</li>\n<li>délivrer : des maux de toute sorte, internes et externes</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λυτρόω-ῶ</b> <span>(<i>ao</i>. ἐλύτρωσα ; <i>pass. ao</i>. ἐλυτρώθην, <i>pf</i>. λελύτρωμαι)</span> délivrer moyennant rançon, DÉM. <i>394, 18 ;</i> ESCHN. <i>29, 36 ;</i> ARSTT. <i>Nic. 9, 2, etc. ;</i> χρημάτων τινά, PLAT. <i>Theæt. 165</i> e, délivrer qqn moyennant une somme d’argent ;<br><b><i>Moy.</i></b> payer une rançon, racheter, <i>acc</i>. POL. <i>17, 16, 1</i>.<br><span><b>Étym</b>. λύτρον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυτροω - λυτρόω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Tite (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3085":"<h1>lutrosis</h1>\n<p>Strong n° 3085 <i>Prononciation [loo'-tro-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un rachat, une rédemption</li>\n<li>délivrance, spéc. de la faute du péché</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λύτρωσις, εως (ἡ)</b> rachat, rançon, rédemption, PLUT. <i>Arat. 11 ;</i> SPT. <i>Lev. 25, 29, etc. ;</i> NT. <i>Luc. 1, 68</i>.<br><span><b>Étym</b>. λυτρόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυτρωσις - λύτρωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G3086":"<h1>lutrotes</h1>\n<p>Strong n° 3086 <i>Prononciation [loo-tro-tace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>rédempteur</li>\n<li>celui qui délivre, libérateur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λυτρωτής, οῦ (ὁ)</b> libérateur, rédempteur, NT. <i>Ap. 7, 35 ;</i> CHRYS. <i>2, 63</i>.<br><span><b>Étym</b>. λυτρόω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυτρωτης - λυτρωτής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT).\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3087":"<h1>luchnia</h1>\n<p>Strong n° 3087 <i>Prononciation [lookh-nee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>un support de lampe (chandelier), candélabre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λυχνία, ας (ἡ)</b> chandelier <i>ou</i> lampe, PLUT. <i>Dio. 9 ;</i> LUC. <i>As. 40, etc</i>.<br><span><b>Étym</b>. λύχνος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυχνια - λυχνία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 11 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Hébreux (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G3088":"<h1>luchnos</h1>\n<p>Strong n° 3088 <i>Prononciation [lookh'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une lampe, une bougie, une chandelle, ce qui est sur un support de lampe ou chandelier</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λύχνος, ου (ὁ) :<br>   I</b> lampe, OD. <i>19, 34 ;</i> BATR. <i>180 ;</i> XÉN. <i>Conv. 7, 4, etc. ;</i> λύχνον ἅπτειν, AR. <i>Nub. 18, etc. ;</i> ARR. <i>Epict. 2, 20, 9, etc. ;</i> ἀνάπτειν, ANACR. <i>31, 15,</i> allumer la lampe ; λύχνος ἡμμένος, THC. <i>4, 133,</i> lampe allumée ; λύχνον σϐεννύναι, PLUT. <i>M. 281</i> f ; ἀποσϐεννύναι, AR. <i>Pl. 668 ;</i> PLUT. <i>M. 702</i> d, éteindre une lampe ; ἀποπληροῦν τοὺς λύχνους ἀποσϐεσθέντας, PLUT. <i>M. 702</i> e, remplir les lampes éteintes ; λύχνος ἀπεσϐήκει, PLAT. <i>Conv. 218</i> b, la lampe s’était éteinte ; περὶ λύχνων ἁφάς, HDT. <i>7, 215 ;</i> DS. <i>19, 31, etc</i>. à l’heure où l’on allume les lampes ; <i>mais</i> λύχνους ἅπτειν, ARR. <i>Epict. 2, 17, 37,</i> illuminer ; <i>p. ext. :</i><br><b>      1</b> flambeau, torche, EUR. <i>Cycl. 514 ;</i><br><b>      2</b> οἱ λύχνοι, AR. <i>Nub. 1065,</i> endroit où l’on achète des lampes ;<br><b>   II</b> lampe, <i>poisson,</i> STR. <i>823</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Plur</i>. -οι, BATR. <i>179 ;</i> AR. <i>Eq. 1315 ;</i> ARR. <i>l. c. ;</i> λύχνα, HDT. <i>2, 133 ;</i> PLUT. <i>Pel. 11, etc</i>.<br><span><b>Étym</b>. <i>p</i>. *λύκ-σν-ος, <i>de indo-europ</i>. *leuk-sn-eh₂-, lune, étoiles, <i>etc., v</i>. λεύσσω ; <i>cf. lat</i>. lūna, lūmen.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυχνος - λύχνος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (6)</li>\n<li>Jean (1)</li>\n<li>2 Pierre (1)</li>\n<li>Apocalypse (3)</li>\n</ul>\n</td></tr>\n</table>","G3089":"<h1>luo</h1>\n<p>Strong n° 3089 <i>Prononciation [loo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>relâcher une personne (ou une chose) attachée ou liée\n<ol type=\"a\">\n<li>bandages des pieds, les chaussures</li>\n<li>un mari et son épouse unis par les liens du mariage</li>\n</ol>\n</li>\n<li>délier des liens, relâcher, rendre libre\n<ol type=\"a\">\n<li>de celui qui est bandé (emmailloté de bandages)</li>\n<li>lié de chaînes (prisonnier), libéré de prison, laisser aller</li>\n</ol>\n</li>\n<li>desserrer, défaire, dissoudre, pour toute chose liée ou amalgamée avec une autre\n<ol type=\"a\">\n<li>une assemblée : congédier, rompre, dissoudre</li>\n<li>lois : qui sont comme des liens</li>\n<li>annuler, renverser</li>\n<li>priver d'autorité, aussi bien par précepte que par action</li>\n<li>déclarer illicite, ou illégal</li>\n<li>détacher ce qui est lié par construction, rompre, casser, démolir, détruire</li>\n<li>dissoudre des choses cohérentes</li>\n<li>métaph., renverser</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>λύω</b> <span>(<i>f</i>. λύσω, <i>ao</i>. ἔλυσα, <i>pf</i>. λέλυκα)</span> <span>[ῡ]</span><br><b>   I</b> délier :<br><b>      1</b> <i>au propre :</i> τινὰ ἐκ τῶν δεσμῶν, PLAT. <i>Rsp. 360</i> c, <i>ou</i> δεσμῶν, ESCHL. <i>Pr. 1005,</i> délivrer qqn de ses liens ; ἵππους ἐξ ὀχέων, IL. <i>5, 369 ;</i> ἵππους ὑπὲξ ὀχέων, IL. <i>8, 504 ;</i> ἵππους ὑφ' ἅρμασιν, IL. <i>18, 244,</i> détacher des chevaux d’un char ; <i>avec un seul rég</i>. λ. ἵππους, OD. <i>4, 35, etc</i>. délier des chevaux ; λ. ζυγόν, ESCHL. <i>Pers. 592,</i> dételer ; λ. κλῇθρα, ESCHL. <i>Sept. 396, etc</i>. délier la courroie qui assujettit un verrou, ouvrir un verrou ; λ. θώρηκα, IL. <i>16, 804,</i> délier une cuirasse ; λ. ζώνην, OD. <i>11, 245, etc</i>. dénouer une ceinture ; <i>fig</i>. λ. στόμα, EUR. <i>Hipp. 1060, etc</i>. délier la bouche, parler librement ; <i>avec le gén. de la partie que l’on délie :</i> λ. τοῦ ποδός, PLUT. <i>Flam. 10,</i> délier le pied ; <i>au pass</i>. ἐλύθη τὰς πέδας, DS. <i>17, 116,</i> il se dégagea de ses entraves ; <i>prov. p. opp. à</i> ἅπτω : <span>λύουσ' εἴθ' ἅπτουσα</span>, SOPH. <i>Ant. 40,</i> déliant <i>ou</i> attachant, <i>càd</i>. quoi que je fasse ;<br><b>      2</b> <i>p. ext</i>. lâcher, laisser aller : ἡνίαν, SOPH. <i>El. 743,</i> lâcher la rêne, <i>p. opp. à</i> « serrer », <i>non</i> « délier », <i>p. opp. à</i> « lier »; λ. τὴν κοιλίαν, ARSTT. <i>Probl. 1, 40,</i> relâcher le ventre ; <i>t. de mar</i>. λ. πρύμνας, EUR. <i>Hec. 539 ;</i> νεῶν πόδα, EUR. <i>Hec. 1020,</i> délier la poupe, le pied des navires, <i>càd</i>. lever l’ancre (<i>propr</i>. laisser aller le navire) ; <i>abs</i>. ANTH. <i>App. 58, 9 ;</i> ἐκ Βενδιδείου, SYN. <i>159</i> c, sortir du port de Bendideion ;<br><b>      3</b> mettre en liberté, délivrer, affranchir : τινά, IL. <i>1, 20, 29, etc</i>. qqn ; εἱρκτῆς τινα, DÉM. <i>764, 11,</i> faire sortir qqn de prison ; λυθεὶς ἀνὴρ ἀντ' ἀνδρός, THC. <i>5, 3,</i> prisonniers échangés homme pour homme ; λύειν τινὰ ἀποίνων, IL. <i>11, 106, ou</i> χρημάτων, HDT. <i>2, 135,</i> mettre qqn en liberté moyennant une rançon, une somme d’argent ; <i>fig</i>. λ. κακότητος, OD. <i>5, 397,</i> délivrer de la maladie ; <i>cf</i>. SOPH. <i>Tr. 181, etc. ; avec une prép</i>. ἐκ πενθέων λ. PD. <i>I. 7, 6 ;</i> λ. ἐκ πόνων, ESCHL. <i>Pr. 873,</i> délivrer de souffrances, d’épreuves pénibles ; <i>de même avec</i> ἀπό <i>et le gén</i>. PLAT. <i>Rsp. 571</i> c ; <i>qqf. avec l’acc. de la chose :</i> παράνομον, ESCHN. <i>82, 15, etc</i>. excuser une illégalité ; φόνῳ φόνον λύειν, SOPH. <i>O.R. 101 ;</i> EUR. <i>Or. 510,</i> faire expier (<i>litt</i>. délier d’) un meurtre par un meurtre ;<br><b>   II</b> dissoudre :<br><b>      1</b> <i>au propre :</i> κυκλίσκους, GAL. dissoudre des pilules ;<br><b>      2</b> <i>p. ext</i>. désagréger, rompre, briser : τάξιν, XÉN. <i>Cyr. 5, 3, 58,</i> faire rompre des rangs, un ordre de bataille ; ἀγορήν, IL. <i>1, 305, etc. ;</i> OD. <i>2, 69, etc. ;</i> XÉN. <i>Œc. 12, 1,</i> dissoudre une assemblée ; γέφυραν, XÉN. <i>An. 2, 4, 19 et 20, etc</i>. rompre un pont ; λελύσθαι ἀπ' ἀλλήλων, XÉN. <i>Cyr. 1, 1, 4,</i> se séparer les uns des autres, <i>en parl. de pers. qui rompent des liens de société ; t. de rhét</i>. λύειν ἐπιστολὴν τῇ συντάξει, D. PHAL. <i>229,</i> écrire une lettre d’un style haché, <i>càd</i>. en phrases courtes, détachées les unes des autres, <i>p. opp. à</i> περιοδεύειν ; <i>t. de gr</i>. résoudre une syllabe longue en deux brèves, DRAC. <i>131, 18 ;</i> HÉPH. <i>h. 5, 6 ; 8, 11, etc. ; fig</i>. τὸ τέλος βίου, SOPH. <i>O.C. 1720 ;</i> βίον, EUR. <i>I.T. 692,</i> terminer (<i>litt</i>. délier) sa vie ; γούνατα λ. τινός, IL. <i>5, 176, etc. ou</i> τινί, IL. <i>22, 335, litt</i>. délier les genoux de qqn, <i>càd</i>. le tuer ; μένος τινί, IL. <i>16, 332,</i> briser la vie de qqn ; <i>au pass</i>. λύεται δέ μου μέλη, EUR. <i>Hec. 438,</i> mes membres sont brisés ; σὴ δὲ βίη λέλυται, IL. <i>8, 103,</i> ta force est brisée ; τοῦ δ' αὖθι λύθη ψυχή τε μένος τε, IL. <i>5, 296,</i> aussitôt son âme et son courage furent brisés ; <i>fig</i>. νόμους, HDT. <i>3, 82 ;</i> DÉM. <i>31, 12,</i> abroger des lois ; σπονδάς, THC. <i>1, 7, 8, etc</i>. rompre des traités ;<br><b>      3</b> mettre fin à, achever, terminer, résoudre : νεῖκος, IL. <i>14, 205 ;</i> OD. <i>7, 74 ;</i> ESCHL. <i>Suppl. 935 ;</i> EUR. <i>Hipp. 1442 ;</i> ἔριν, EUR. <i>Ph. 81 ;</i> ANTH. <i>9, 316,</i> mettre fin à une querelle ;<br><b>      4</b> résoudre, expliquer : αἴνιγμα, LUC. <i>Herc. 4,</i> résoudre une énigme ;<br><b>      5</b> se libérer de : μαντεῖα, SOPH. <i>O.R. 407,</i> de la prédiction d’un oracle (par le fait qu’elle s’accomplit) ; <i>cf</i>. EUR. <i>Suppl. 39 ;</i> μισθοῦ, XÉN. <i>Ages. 2, 31,</i> acquitter, <i>càd</i>. payer une part de solde ; <i>abs</i>. réfuter un argument, procéder à la réfutation, ARSTT. <i>Rhet. 1, 1 ; cf. 2, 25 :</i> τέλη, SOPH. <i>O.R. 316,</i> payer les frais (<i>cf</i>. λυσιτελεῖν), <i>d’où</i> être avantageux ; <i>p. suite, abs</i>. λύει, <i>avec un inf</i>. EUR. <i>Med. 1112,</i> il est avantageux de, <i>etc. ;</i> λύει ἄλγος, EUR. <i>Med. 1362,</i> la souffrance est utile ; λύει ἐμοί, <i>avec un inf</i>. EUR. <i>Med. 566,</i> il m’est avantageux de, <i>etc. ; avec une prop. inf</i>. il est utile que, <i>etc</i>. XÉN. <i>An. 3, 4, 36 ; au pass</i>. λελύσθαι μοι δοκεῖ καὶ ἡ ἐκείνων ὕϐρις καὶ ἡ ἡμετέρα ὑποψία, XÉN. <i>An. 3, 1, 21,</i> il me semble que tout cela a mis fin à leur insolence et à notre défiance ; πᾶς ὁ παρὼν φόϐος λελύσεται, DÉM. <i>178, 20,</i> toute la crainte présente aura été utile ;<br><b><i>Moy</i>. λύομαι</b> <span>(<i>f</i>. λύσομαι, <i>etc</i>.)</span> <span>[ῡ, <i>excepté au pf</i>.]</span><br><b>   I <i>tr</i>.<br>      1</b> délier de dessus soi : ἱμάντα, IL. <i>14, 214,</i> délier sa ceinture ;<br><b>      2</b> délier pour soi : τεύχεα, IL. <i>17, 318,</i> délier (pour les prendre) les armures (des morts) ; <i>p. ext</i>. délivrer, affranchir pour soi : θύγατρα, IL. <i>17, 12,</i> délivrer sa fille en payant rançon ; délivrer, <i>en gén. :</i> τινά τινος, HÉS. <i>Th. 528,</i> affranchir qqn de qqe ch. ; <i>abs</i>. λ. τινα, PD. <i>I. 7, 55 ;</i> PLAT. <i>Menex. 243</i> c, délivrer <i>ou</i> affranchir qqn ; αἰχμαλώτους, DÉM. <i>412, 21,</i> délivrer des prisonniers de guerre ;<br><b>   II <i>intr.</i></b> se relâcher : λύτο γούνατα, IL. <i>21, 114,</i> ses genoux se dérobèrent sous lui.<br><span><b><span class=\"arrow\"></span></b> <i>Pass. ao. 3 pl. épq</i>. λύθεν (<i>p</i>. ἐλύθησαν) IL. <i>16, 805 ;</i> EMPÉD. <i>15, 4 Diels. Pf. opt. 3 pl</i>. λελῦντο, OD. <i>18, 238. — Moy. ao.2 au sens pass</i>. λύμην, IL. <i>21, 80 ; 3 sg</i>. λύτο, IL. <i>21, 114 ;</i> OPP. <i>H. 2, 71 ; 3 pl</i>. λύντο, IL. <i>7, 16. — Au prés. et à l’impf</i>. <span>[ῠ]</span> <i>dans Homère (mais</i> <span>[ῡ]</span>, <i>à l’arsis,</i> IL. <i>23, 513 ;</i> OD. <i>7, 74</i>), <span>[ῡ]</span> <i>attique ; aux fut. et ao. act. et moy</i>. <span>[ῡ]</span> ; <i>aux fut., ao., pf. et pl.q.pf. pass</i>. <span>[ῠ]</span> ; <i>aux pf. et pl.q.pf. act</i>. <span>[ῡ]</span> ; <i>à l’ao.2 moy</i>. λύτο <span>[ῠ]</span> IL. <i>21, 114 ;</i> OPP. <i>H. 2, 71 ; mais</i> <span>[ῡ]</span> IL. <i>24, 1</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *lh₁u-, couper, détacher ; <i>cf</i>. λύσις, λυτήρ ; <i>lat</i>. luō, solvō.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">λυω - λύω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n43 fois dans 39 versets de 10 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (5)</li>\n<li>Luc (7)</li>\n<li>Jean (7)</li>\n<li>Actes (6)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>2 Pierre (3)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (6)</li>\n</ul>\n</td></tr>\n</table>","G3090":"<h1>Lois</h1>\n<p>Strong n° 3090 <i>Prononciation [lo-ece']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Loïs (Angl. Lois) = « agréable »\n<ol><li>la grand-mère de Timothée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λωις - Λωΐς</font>\n<br><br>origine incertaine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G3091":"<h1>Lot</h1>\n<p>Strong n° 3091 <i>Prononciation [lote]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Lot = « voile ou couverture »\n<ol><li>le fils de Haran et neveu d'Abraham</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Λωτ</font> &lt; לוט - <font face=\"Georgia\">Λώτ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (3)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G3092":"<h1>Maath</h1>\n<p>Strong n° 3092 <i>Prononciation [mah-ath']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Maath = « petit »\n<ol><li>le fils de Mattathias dans la généalogie de Jésus-Christ</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μααθ</font> &lt; מחת - <font face=\"Georgia\">Μάαθ</font>\n<br><br>probablement Hébreu d'origine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G3093":"<h1>Magdala</h1>\n<p>Strong n° 3093 <i>Prononciation [mag-dal-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Magadan (Angl. Magdala) = « une tour »\n<ol><li>lieu sur la côte ouest du Lac de Galilée, à 5 km de Tibériade</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μαγδαλα</font> &lt; מגדלא - <font face=\"Georgia\">Μαγαδάν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G3094":"<h1>Magdalene</h1>\n<p>Strong n° 3094 <i>Prononciation [mag-dal-ay-nay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Magdala (Angl. Magdalene) = « une tour »\n<ol><li>nom donné à Marie-Madeleine, l'identifiant comme venant de Magdala (Magadan)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Μαγδαληνή, ῆς (ἡ)</b> <i>propr</i>. « originaire de Magdala », <i>n. de Marie-Madeleine,</i> NT. <i>Matth. 27, 56</i>.<br><span><b>Étym</b>. Μαγδαλά.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μαγδαλνη - Μαγδαληνή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 4 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (4)</li>\n<li>Luc (2)</li>\n<li>Jean (3)</li>\n</ul>\n</td></tr>\n</table>","G3095":"<h1>mageia</h1>\n<p>Strong n° 3095 <i>Prononciation [mag-i'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>magie, actes de magie, sorcellerie</li>\n<li>religion des mages</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μαγεία, ας (ἡ)</b> <span>[μᾰ]</span><br><b>      1</b> religion des mages, PLAT. <i>1 Alc. 122</i> a ;<br><b>      2</b> magie, sorcellerie, TH. <i>H.P. 9, 15, 7</i>.<br><span><b>Étym</b>. μάγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μαγεια - μαγεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3096":"<h1>mageuo</h1>\n<p>Strong n° 3096 <i>Prononciation [mag-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être un magicien, pratiquer des actes de magie, accomplir des opérations magiques</li>\n<li>charmer par des sortilèges</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μαγεύω</b> <span>(<i>ao</i>. ἐμάγευσα, <i>pf. pass</i>. μεμάγευμαι)</span> <span>[ᾰ]</span><br><b>   I <i>intr</i>.<br>      1</b> être magicien, PLUT. <i>Artax. 3, etc. ;</i> PHILSTR. <i>V. Ap. 1, 2, p. 4 ;</i><br><b>      2</b> user de moyens magiques, accomplir des opérations magiques, EUR. <i>I.T. 1338 ;</i> PLUT. <i>Num. 15 ;</i><br><b>   II <i>tr</i>.<br>      1</b> charmer par des sortilèges, CLÉARQ. (ATH. <i>256</i> e) ; LUC. <i>As. 54 ;</i><br><b>      2</b> façonner par un art magique, <i>acc</i>. ANTH. <i>12, 57</i>.<br><span><b>Étym</b>. μάγος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μαγευω - μαγεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G3097":"<h1>magos</h1>\n<p>Strong n° 3097 <i>Prononciation [mag'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un mage\n<ol type=\"a\">\n<li>le nom donné par les Babyloniens (Chaldéens), Mèdes, Perses, et autres, aux hommes sages, enseignants, prêtres, médecins, astrologues, voyants, interprètes de rêves, augures, devins, sorciers etc.</li>\n<li>les hommes sages orientaux (astrologues) qui, ayant découvert le lever d'une étoile remarquable, ont su que le Messie venait de naître, et sont venus à Jérusalem pour l'adorer</li>\n<li>un faux prophète et sorcier</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>μάγος, ου</b> <span>[ᾰ]</span><br><b>      1 (ὁ)</b> mage, <i>prêtre interprète des songes, chez les Mèdes,</i> HDT. <i>7, 37, etc. ;</i> XÉN. <i>Cyr. 8, 1, 23 ; chez les Perses,</i> LUC. <i>Macr. 4, etc. ;</i><br><b>      2 (ὁ, ἡ)</b> magicien, sorcier, SOPH. <i>O.R. 387 ;</i> EUR. <i>Or. 1497 ;</i> PLAT. <i>Rsp. 572</i> e, <i>Ax. 371</i> a ; <i>fém</i>. ANTH. <i>5, 16 ;</i> LUC. <i>As. 4 ;</i><br><b>      3 (ὁ)</b> <i>sorte d’emplâtre,</i> AÉT. <i>10, 24</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">μαγος - μάγος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G3098":"<h1>Magog</h1>\n<p>Strong n° 3098 <i>Prononciation [mag-ogue']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Magog = « qui domine, territoire de montagne »\n<ol>\n<li>terre au nord d'Israël d'où vint le roi de Gog pour attaquer Israël</li>\n<li>Magog avec Gog, ennemi de Dieu à la fin des temps</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μαγωγ</font> &lt; מגוג - <font face=\"Georgia\">Μαγώγ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G3099":"<h1>Madian</h1>\n<p>Strong n° 3099 <i>Prononciation [mad-ee-on']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Madian = « lutte, dispute »\n<ol><li>terre proche de la Mer Rouge, et qui prend son nom de l'un des fils d'Abraham par Ketura</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Μαδιαν</font> &lt; מדין - <font face=\"Georgia\">Μαδιάμ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>"};
